begin;
    with j as (select * from jsonb_to_recordset($law7v019$[{"code_id":"KoAP_RF","article_number":"5.31","version_date":"2001-12-30","article_text":"1. Нарушение или невыполнение работодателем или лицом, его представляющим, обязательств по коллективному договору, соглашению, за исключением случаев, предусмотренных частью 2 настоящей статьи, -\n\nвлечет предупреждение или наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.\n\n2. Нарушение или невыполнение работодателем или лицом, его представляющим, обязательств по коллективному договору, соглашению в части, касающейся охраны труда работников, занятых на работах с вредными и (или) опасными условиями труда, в том числе на подземных работах, -\n\nвлечет предупреждение или наложение административного штрафа в размере от шести тысяч до десяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 27.11.2023 № 559-ФЗ)","article_title":"Статья 5.31. Нарушение или невыполнение обязательств по коллективному договору, соглашению","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b20b7d195f9f09190036d6520e7b8df2e4aa1a691a8ddafaedcc3ee6b1e0b3e0"},{"code_id":"KoAP_RF","article_number":"5.32","version_date":"2001-12-30","article_text":"Уклонение работодателя или его представителя от получения требований работников и от участия в примирительных процедурах, в том числе непредоставление помещения для проведения собрания (конференции) работников в целях выдвижения требований или создание препятствий проведению такого собрания (такой конференции), -\n\nвлечет наложение административного штрафа в размере от одной тысячи до трех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.32. Уклонение от получения требований работников и от участия в примирительных процедурах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"15d5f0f0686608e9f0001a89d8531fbd0c99e57b64c021e4c1d872b946660526"},{"code_id":"KoAP_RF","article_number":"5.33","version_date":"2001-12-30","article_text":"Невыполнение работодателем или его представителем обязательств по соглашению, достигнутому в результате примирительной процедуры, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до четырех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.33. Невыполнение соглашения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c3fed35f7ce15f45cce71784583fbbe23dd2cecaa3bc07186dc39624fae0b5c"},{"code_id":"KoAP_RF","article_number":"5.34","version_date":"2001-12-30","article_text":"Увольнение работников в связи с коллективным трудовым спором и объявлением забастовки -\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.34. Увольнение работников в связи с коллективным трудовым спором и объявлением забастовки","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e5229ca65713272fb4f2e354afbaab6a5791924a68b953216318a2347d1c70c"},{"code_id":"KoAP_RF","article_number":"5.35","version_date":"2001-12-30","article_text":"влечет предупреждение или наложение административного штрафа в размере от пятисот до двух тысяч рублей. (В редакции  федеральных законов от 22.06.2007 № 116-ФЗ, от 31.07.2025 № 302-ФЗ)\n\nвлечет наложение административного штрафа в размере от двух тысяч до трех тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 04.05.2011 № 98-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до пяти суток.\n\n(Дополнение частью - Федеральный закон от 04.05.2011 № 98-ФЗ)","article_title":"Статья 5.35. Неисполнение родителями или иными законными представителями несовершеннолетних обязанностей по содержанию и воспитанию несовершеннолетних","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"920649ee12c969fe70eb4fdc704eafd947323c8767fd2c1e9b10d1b4c02a7a94"},{"code_id":"KoAP_RF","article_number":"5.351","version_date":"2001-12-30","article_text":"влечет обязательные работы на срок до ста пятидесяти часов либо административный арест на срок от десяти до пятнадцати суток или наложение административного штрафа на лиц, в отношении которых в соответствии с настоящим Кодексом не могут применяться обязательные работы либо административный арест, в размере двадцати тысяч рублей.\n\nвлечет обязательные работы на срок до ста пятидесяти часов либо административный арест на срок от десяти до пятнадцати суток или наложение административного штрафа на лиц, в отношении которых в соответствии с настоящим Кодексом не могут применяться обязательные работы либо административный арест, в размере двадцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 03.07.2016 № 326-ФЗ)","article_title":"Статья 5.351. Неуплата средств на содержание детей или нетрудоспособных родителей","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fff96805e79aeeb8c83db3a4f4692d2dd05447168c1fc3d7b4c30e930505b2d"},{"code_id":"KoAP_RF","article_number":"5.36","version_date":"2001-12-30","article_text":"1. Нарушение руководителем учреждения, в котором находятся дети, оставшиеся без попечения родителей, либо должностным лицом органа исполнительной власти субъекта Российской Федерации или органа местного самоуправления порядка или сроков предоставления сведений о несовершеннолетнем, нуждающемся в передаче на воспитание в семью (на усыновление (удочерение), под опеку (попечительство) или в приемную семью) либо в учреждение для детей-сирот или для детей, оставшихся без попечения родителей, а равно предоставление заведомо недостоверных сведений о таком несовершеннолетнем -\n\nвлечет наложение административного штрафа в размере от одной тысячи до одной тысячи пятисот рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Совершение руководителем учреждения, в котором находятся дети, оставшиеся без попечения родителей, либо должностным лицом органа исполнительной власти субъекта Российской Федерации или органа местного самоуправления действий, направленных на укрытие несовершеннолетнего от передачи на воспитание в семью (на усыновление (удочерение), под опеку (попечительство) или в приемную семью) либо в учреждение для детей-сирот или для детей, оставшихся без попечения родителей, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до трех тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.36. Нарушение порядка или сроков предоставления сведений о несовершеннолетних, нуждающихся в передаче на воспитание в семью либо в учреждения для детей-сирот или для детей, оставшихся без попечения родителей","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"140153560080a0e9d5fd819db6a76015b00e5f6767f0e1ace61ad2d108068d81"},{"code_id":"KoAP_RF","article_number":"5.37","version_date":"2001-12-30","article_text":"Незаконные действия по усыновлению (удочерению) ребенка, передаче его под опеку (попечительство) или в приемную семью -\n\nвлекут наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч пятисот рублей; на должностных лиц - от четырех тысяч до пяти тысяч рублей; на юридических лиц - от двухсот тысяч до пятисот тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 05.04.2013 № 58-ФЗ)","article_title":"Статья 5.37. Незаконные действия по усыновлению (удочерению) ребенка, передаче его под опеку (попечительство) или в приемную семью","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e96ed6987f6ecf44ee83baf15ab3aac4a3eaaa1e95b47112488943d791c980d"},{"code_id":"KoAP_RF","article_number":"5.38","version_date":"2001-12-30","article_text":"Воспрепятствование организации или проведению собрания, митинга, демонстрации, шествия или пикетирования, проводимых в соответствии с законодательством Российской Федерации, либо участию в них, а равно принуждение к участию в них -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до двадцати тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 08.06.2012 № 65-ФЗ)","article_title":"Статья 5.38. Нарушение законодательства о собраниях, митингах, демонстрациях, шествиях и пикетировании","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25fa6df9b658e2899fcd29cdfbca30a27d41ce32ed1616543c1cd7012706d1b0"},{"code_id":"KoAP_RF","article_number":"5.39","version_date":"2001-12-30","article_text":"Неправомерный отказ в предоставлении гражданину, в том числе адвокату в связи с поступившим от него адвокатским запросом, и (или) организации информации, предоставление которой предусмотрено федеральными законами, несвоевременное ее предоставление либо предоставление заведомо недостоверной информации - (В редакции Федерального закона от 02.06.2016 № 160-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей. (В редакции Федерального закона от 01.07.2017 № 146-ФЗ)\n\n(Статья в редакции Федерального закона от 31.05.2010 № 108-ФЗ)","article_title":"Статья 5.39. Отказ в предоставлении информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8125f285bf910e3a1af7708288d87eb62644ffe9569253a92c416231a6aeada1"},{"code_id":"KoAP_RF","article_number":"5.4","version_date":"2001-12-30","article_text":"Нарушение установленного законом порядка представления сведений об избирателях, участниках референдума либо представление недостоверных сведений об избирателях, участниках референдума соответствующим избирательным комиссиям должностным лицом, на которое законом возложена эта обязанность, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.4. Нарушение порядка представления сведений об избирателях, участниках референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a73b75916c37d7766d9bfceb5e6715a3b14be045f55d57e670e9c439b3c1182f"},{"code_id":"KoAP_RF","article_number":"5.40","version_date":"2001-12-30","article_text":"Принуждение к участию или к отказу от участия в забастовке путем насилия или угроз применения насилия либо с использованием зависимого положения принуждаемого -\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.40. Принуждение к участию или к отказу от участия в забастовке","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"401db1ce923cc01c210257e0d2ce3a96b405b7caa0e197ee0cb02496934f97cc"},{"code_id":"KoAP_RF","article_number":"5.41","version_date":"2001-12-30","article_text":"Непредоставление на безвозмездной основе услуг, предусмотренных гарантированным перечнем услуг по погребению, а равно невыплата социального пособия на погребение супругу, близким родственникам, иным родственникам, законному представителю умершего или иному лицу, взявшему на себя обязанность осуществить погребение умершего, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.41. Непредоставление на безвозмездной основе услуг по погребению, невыплата социального пособия на погребение","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c76ef970ce9e54e1abe18e9fd31963a42b8c0c960bde0f65230d191ed0995a2c"},{"code_id":"KoAP_RF","article_number":"5.42","version_date":"2001-12-30","article_text":"1. Неисполнение работодателем обязанности по выполнению квоты для приема на работу инвалидов, за исключением случаев освобождения работодателя от выполнения установленной квоты, либо отказ работодателя в приеме на работу инвалида в пределах установленной квоты -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на индивидуальных предпринимателей - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Часть в редакции  Федерального закона от 09.11.2024 № 382-ФЗ)\n\n2. Необоснованный отказ в регистрации инвалида в качестве безработного -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 23.02.2013 № 11-ФЗ)","article_title":"Статья 5.42. Нарушение прав инвалидов в области трудоустройства и занятости","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00567ff0e7b7b35a599f0bc090dffe9cf6fae5911b48fa63da5b770b0bc22ac3"},{"code_id":"KoAP_RF","article_number":"5.43","version_date":"2001-12-30","article_text":"Нарушение требований законодательства, предусматривающих выделение на автомобильных стоянках (остановках) мест для специальных автотранспортных средств инвалидов, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 04.06.2011 № 127-ФЗ)","article_title":"Статья 5.43. Нарушение требований законодательства, предусматривающих выделение на автомобильных стоянках (остановках) мест для специальных автотранспортных средств инвалидов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0835ed6c867f16f475f49f19a604c96cd087387debed45fa3f17c09cc1889605"},{"code_id":"KoAP_RF","article_number":"5.44","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 24.07.2009 № 213-ФЗ)","article_title":"Статья 5.44. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"098c64930db4540e08e8e36b98f8459df71c522fd32cf3bd945ef1a9adab7ae6"},{"code_id":"KoAP_RF","article_number":"5.45","version_date":"2001-12-30","article_text":"Использование лицом, замещающим государств\n\nенную или муниципальную должность, либо находящимся на государственной или муниципальной службе, либо являющимся членом органа управления организации независимо от формы собственности (в организации, высшим органом управления которой является собрание, - членом органа, осуществляющего руководство деятельностью этой организации), за исключением политической партии, преимуществ своего должностного или служебного положения в целях выдвижения и (или) избрания кандидата, списка кандидатов, выдвижения и (или) поддержки инициативы проведения референдума, получения того или иного ответа на вопрос (вопросы) референдума -  (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.45. Использование преимуществ должностного или служебного положения в период избирательной кампании, кампании референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"871253231a6a6a87e5455fd867de383ab02c81381ca06593eb2603dc4f618086"},{"code_id":"KoAP_RF","article_number":"5.46","version_date":"2001-12-30","article_text":"Подделка подписей избирателей, участников референдума, собираемых в поддержку выдвижения кандидата, списка кандидатов, инициативы проведения референдума, а равно заверение заведомо подделанных подписей (подписных листов) лицом, осуществляющим сбор подписей избирателей, либо уполномоченным лицом, если эти действия не содержат уголовно наказуемого деяния, - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от двух тысяч до двух тысяч пятисот рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.46. Подделка подписей избирателей, участников референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8cab9f81ef1347eb625427507feae8e5a9f2ec9ca51df0ceefb330d80abd24c"},{"code_id":"KoAP_RF","article_number":"5.47","version_date":"2001-12-30","article_text":"Участие органов государственной власти, органов местного самоуправления, органов управления организаций независимо от формы собственности, учреждений, членов избирательных комиссий с правом решающего голоса в сборе подписей избирателей в поддержку выдвижения кандидата, списка кандидатов, в сборе подписей участников референдума в поддержку инициативы проведения референдума, а равно сбор подписей на рабочих местах, в процессе и в местах выдачи заработной платы, пенсий, пособий, иных социальных выплат, а также при оказании благотворительной помощи - (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 09.03.2016 № 66-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.47. Сбор подписей избирателей, участников референдума в запрещенных местах, а также сбор подписей лицами, которым участие в этом запрещено федеральным законом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05af4d89ef6610d2610c094b8fefaf4b34fdcc1d8f297c696aa0f8d9fafde13a"},{"code_id":"KoAP_RF","article_number":"5.48","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nНарушение прав зарегистрированных кандидатов, избирательных объединений, инициативных групп по проведению референдума, иных групп участников референдума на размещение агитационных материалов на объекте, находящемся в государственной или муниципальной собственности либо в собственности организации, в уставном (складочном) капитале которой доля (вклад) Российской Федерации, субъектов Российской Федерации и (или) муниципальных образований на день официального опубликования (публикации) решения о назначении выборов, регистрации инициативной группы по проведению референдума превышает 30 процентов, а равно нарушение организациями, оказывающими рекламные услуги, условий размещения агитационных материалов - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч пятисот до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.48. Нарушение прав зарегистрированных кандидатов, избирательных объединений, инициативных групп по проведению референдума, иных групп участников референдума при выделении площадей для размещения агитационных материалов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb10ad53b161ebb5edd4be4c11217294638eb2aa220346f0102ac05dfa502071"},{"code_id":"KoAP_RF","article_number":"5.49","version_date":"2001-12-30","article_text":"Нарушение запрета на проведение в период избирательной кампании, кампании референдума лотерей и других основанных на риске игр, в которых выигрыш призов или участие в розыгрыше призов зависит от итогов голосования, результатов выборов, референдума либо которые иным образом связаны с выборами, референдумом, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от трех тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.49. Нарушение запрета на проведение в период избирательной кампании, кампании референдума лотерей и других основанных на риске игр, связанных с выборами и референдумом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"681e9a1779a514650a78264407ec18adaa9030ec9785cdf2f284cbcff10fffad"},{"code_id":"KoAP_RF","article_number":"5.5","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до двух тысяч пятисот рублей, на должностных лиц - от одной тысячи до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до ста тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до четырех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.5. Нарушение порядка участия средств массовой информации в информационном обеспечении выборов, референдумов, общероссийского голосования","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b96d9e3cad74390866656359f7c452c0d76e7e03944bfedcabba140d9b3c2094"},{"code_id":"KoAP_RF","article_number":"5.50","version_date":"2001-12-30","article_text":"Невозврат жертвователю в установленный законодательством о выборах и референдумах срок пожертвований (их части), перечисленных в избирательный фонд, фонд референдума с нарушением требований законодательства о выборах и референдумах, неперечисление в указанный срок в доход соответствующего бюджета пожертвований, внесенных анонимными жертвователями, - (В редакции Федерального закона от 09.02.2009 № 3-ФЗ)\n\nвлечет наложение административного штрафа на кандидата, на лицо, являвшееся кандидатом, на лицо, избранное депутатом, на уполномоченного представителя по финансовым вопросам инициативной группы по проведению референдума, иной группы участников референдума в размере от десяти тысяч до двадцати тысяч рублей; на избирательное объединение - от ста тысяч до трехсот тысяч рублей. (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 22.06.2007 № 116-ФЗ; от 24.11.2014 № 355-ФЗ)\n\nПримечание. (Примечание утратило силу - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.50. Нарушение правил перечисления средств, внесенных в избирательный фонд, фонд референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"040d415bdc82982059b80390bed81bf0c76872baae682e2ba6ef2e55caff66dc"},{"code_id":"KoAP_RF","article_number":"5.51","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (Утратила силу - Федеральный закон от 09.03.2016 № 66-ФЗ)","article_title":"Статья 5.51. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60ff4c9d58e917c921753b72e13681d707a33e47ae708726f861a4ef55f9b030"},{"code_id":"KoAP_RF","article_number":"5.52","version_date":"2001-12-30","article_text":"Невыполнение уполномоченным на то должностным лицом требований об обеспечении зарегистрированным кандидатам, избирательным объединениям равных условий для проведения агитационных публичных мероприятий в случаях, когда обеспечение таких условий предусмотрено законом, либо иное нарушение предусмотренных законодательством о выборах прав зарегистрированного кандидата, избирательного объединения при проведении ими указанных мероприятий -\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 04.07.2003 № 94-ФЗ) (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.52. Невыполнение уполномоченным лицом требований законодательства о выборах об обеспечении кандидатам, избирательным объединениям равных условий для проведения агитационных публичных мероприятий","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c4819af17bbb0800aad661eecb1c9090ed635efea4a11d80a4546cd9718d725"},{"code_id":"KoAP_RF","article_number":"5.53","version_date":"2001-12-30","article_text":"Незаконные действия по получению и (или) распространению информации, составляющей кредитную историю, если такие действия не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч пятисот рублей; на должностных лиц - от двух тысяч пятисот до пяти тысяч рублей или дисквалификацию на срок до трех лет; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.53. Незаконные действия по получению и (или) распространению информации, составляющей кредитную историю","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a85aca8ca7118db3a491868e79743b11edcf5020463c1dfd616a97a06e64b157"},{"code_id":"KoAP_RF","article_number":"5.54","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.12.2013 № 375-ФЗ)\n\n1. Непроведение проверки или несвоевременное проведение по требованию субъекта кредитной истории проверки бюро кредитных историй информации, содержащейся в кредитной истории (кредитном отчете), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от одной тысячи до двух тысяч пятисот рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Незаконный отказ бюро кредитных историй в исправлении недостоверной информации или неисполнение обязанности по исправлению недостоверной информации, содержащейся в кредитной истории (кредитном отчете), -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двух тысяч до пяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.54. Неисполнение обязанности по проведению проверки и (или) исправлению недостоверной информации, содержащейся в кредитной истории (кредитном отчете)","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"167d595d0e085ba02a73cb8b1efb437702a16c2068b0101c1856217f80bc2bc7"},{"code_id":"KoAP_RF","article_number":"5.55","version_date":"2001-12-30","article_text":"Непредоставление бюро кредитных историй кредитного отчета, предоставление неполного или недостоверного кредитного отчета, а также несвоевременное предоставление кредитного отчета в случаях, если такое предоставление осуществляется или должно осуществляться в соответствии с Федеральным законом \"О кредитных историях\", -\n\nвлекут наложение административного штрафа на должностных лиц в размере от одной тысячи до двух тысяч пятисот рублей; на юридических лиц - от двадцати тысяч до пятидесяти тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.12.2004 № 219-ФЗ)","article_title":"Статья 5.55. Непредоставление кредитного отчета","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ec40152a9d45f74f996e91e48266fcccfa69b3b9c34b4c06b5db97f9fc0553f"},{"code_id":"KoAP_RF","article_number":"5.56","version_date":"2001-12-30","article_text":"1. Непредставление председателем, заместителем председателя или секретарем избирательной комиссии, комиссии референдума в вышестоящую избирательную комиссию, комиссию референдума документов, связанных с подготовкой и проведением выборов, референдума, или их представление с нарушением установленных законом сроков -\n\nвлечет наложение административного штрафа в размере от двух тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n2. Уничтожение документов, связанных с подготовкой и проведением выборов, референдума, до истечения сроков их хранения, а также нарушение установленного порядка уничтожения таких документов -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 21.07.2005 № 93-ФЗ)","article_title":"Статья 5.56. Нарушение порядка и сроков представления и хранения документов, связанных с подготовкой и проведением выборов, референдума","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63fb0260b85e0a486f32051b839a5a08a7d3e28086df272379ff296005b74883"},{"code_id":"KoAP_RF","article_number":"5.57","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n\n1. Нарушение или незаконное ограничение права на образование, выразившиеся в нарушении или ограничении права на получение общедоступного и бесплатного образования, а равно незаконные отказ в приеме в образовательную организацию либо отчисление (исключение) из образовательной организации -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\nвлечет дисквалификацию на срок от одного года до двух лет.\n\n(Дополнение статьей - Федеральный закон от 03.06.2009 № 104-ФЗ)","article_title":"Статья 5.57. Нарушение права на образование и предусмотренных законодательством об образовании прав и свобод обучающихся образовательных организаций","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"529b1d5f8fac3e3fea18a3a5c2b044e2c32f4f9901d2970b3093ff5a066fddb8"},{"code_id":"KoAP_RF","article_number":"5.58","version_date":"2001-12-30","article_text":"1. Нарушение установленного законодательством о выборах и референдумах порядка выдачи открепительного удостоверения либо невыполнение требования об изъятии открепительного удостоверения или отрывного талона открепительного удостоверения либо нарушение порядка использования специального знака (марки) при включении избирателя, участника референдума в список избирателей, участников референдума -\n\nвлечет наложение административного штрафа в размере от одной тысячи до двух тысяч пятисот рублей.\n\n2. Использование заведомо поддельных открепительного удостоверения или специального знака (марки) -\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до трех тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 04.10.2010 № 263-ФЗ) (В редакции Федерального закона от 01.06.2017 № 104-ФЗ)","article_title":"Статья 5.58. Нарушение установленного законодательством о выборах и референдумах порядка выдачи открепительного удостоверения и невыполнение требований о его изъятии. Нарушение порядка использования специального знака (марки). Использование заведомо поддельных открепительного удостоверения или специального знака (марки)","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9f87faabaedc2f6d2566aef1ecb3c938c39c9f352c0db5c7d5e84c01af1736b"},{"code_id":"KoAP_RF","article_number":"5.59","version_date":"2001-12-30","article_text":"Нарушение установленного законодательством Российской Федерации порядка рассмотрения обращений граждан, объединений граждан, в том числе юридических лиц, должностными лицами государственных органов, органов местного самоуправления, государственных и муниципальных учреждений и иных организаций, на которые возложено осуществление публично значимых функций, за исключением случаев, предусмотренных статьями 5.39, 5.63 настоящего Кодекса, -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до десяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 11.07.2011 № 199-ФЗ) (В редакции Федерального закона от 07.05.2013 № 80-ФЗ)","article_title":"Статья 5.59. Нарушение порядка рассмотрения обращений граждан","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29403ce81b9235438a5149a93717e7a4b94ea95be678e4369145a0dc80428c80"},{"code_id":"KoAP_RF","article_number":"5.6","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\n(Дополнение частью - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.6. Нарушение прав члена избирательной комиссии, комиссии референдума, наблюдателя, иностранного (международного) наблюдателя, доверенного лица или уполномоченного представителя кандидата, избирательного объединения, члена или уполномоченного представителя инициативной группы по проведению референдума, иной группы участников референдума либо представителя средства массовой информации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c84aa3cbd76c9ef731609d65c28a411fb2f797f4b42af3efcf9674c5702fb916"},{"code_id":"KoAP_RF","article_number":"5.60","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ) (Утратила силу - Федеральный закон от 28.07.2012 № 141-ФЗ)","article_title":"Статья 5.60. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f6bc7949f4430ff2d0c560808cc0bb87c3d467a7fce6c7d2b402a2edddb3e08"},{"code_id":"KoAP_RF","article_number":"5.61","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей. (В редакции Федерального закона от 30.12.2020 № 513-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до десяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на юридических лиц - от двухсот тысяч до семисот тысяч рублей. (В редакции Федерального закона от 30.12.2020 № 513-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей. (В редакции Федерального закона от 30.12.2020 № 513-ФЗ)\n\nвлечет наложение административного штрафа в размере от пятидесяти тысяч до ста тысяч рублей либо дисквалификацию на срок до одного года.\n\n(Дополнение частью - Федеральный закон от 30.12.2020 № 513-ФЗ)\n\nвлечет наложение административного штрафа в размере от ста тысяч до ста пятидесяти тысяч рублей либо дисквалификацию на срок до двух лет.\n\n(Дополнение частью - Федеральный закон от 30.12.2020 № 513-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ)","article_title":"Статья 5.61. Оскорбление","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afb0b2d2a41432d6db64c371baa8432a4659db8dbc40f3a1415aee60b3ee81ce"},{"code_id":"KoAP_RF","article_number":"5.611","version_date":"2001-12-30","article_text":"Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, -\n\nвлечет наложение административного штрафа на юридических лиц в размере от пятисот тысяч до трех миллионов рублей.\n\n(Дополнение статьей - Федеральный закон от 30.12.2020 № 513-ФЗ)","article_title":"Статья 5.611. Клевета","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a073ededca32c1c8d1426818d5dee7197390ad3e2b0802f5c1c4293cb235fd40"},{"code_id":"KoAP_RF","article_number":"5.62","version_date":"2001-12-30","article_text":"Дискриминация, то есть нарушение прав, свобод и законных интересов человека и гражданина в зависимости от его пола, расы, цвета кожи, национальности, языка, происхождения, имущественного, семейного, социального и должностного положения, возраста, места жительства, отношения к религии, убеждений, принадлежности или непринадлежности к общественным объединениям или каким-либо социальным группам, -   (В редакции Федерального закона от 02.07.2013 № 162-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 07.12.2011 № 420-ФЗ)","article_title":"Статья 5.62. Дискриминация","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9707022aaf9ec06ea6faf06fac0c5186f0e2e1b6b856ae3da08a544fc06da95c"},{"code_id":"KoAP_RF","article_number":"5.63","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на должностных лиц федеральных органов исполнительной власти или органов государственных внебюджетных фондов Российской Федерации в размере от трех тысяч до пяти тысяч рублей; на работников многофункциональных центров, работников иных организаций, осуществляющих в со\n\nответствии с законодательством Российской Федерации функции многофункционального центра, работников публично-правовой компании, осуществляющей оказание государственных услуг в сфере государственного кадастрового учета и государственной регистрации прав, - от одной тысячи до одной тысячи пятисот рублей. (В редакции  федеральных законов от 28.07.2012 № 133-ФЗ, от 30.11.2024 № 420-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц органов исполнительной власти субъектов Российской Федерации или органов местного самоуправления, осуществляющих исполнительно-распорядительные полномочия, в размере от трех тысяч до пяти тысяч рублей.\n\n(Дополнение частью - Федеральный закон от 28.12.2013 № 430-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, органов местного самоуправления, осуществляющих исполнительно-распорядительные полномочия, или органов государственных внебюджетных фондов Российской Федерации в размере от пяти тысяч до десяти тысяч рублей; на работников многофункциональных центров, работников иных организаций, осуществляющих в соответствии с законодательством Российской Федерации функции многофункционального центра, работников публично-правовой компании, осуществляющей оказание государственных услуг в сфере государственного кадастрового учета и государственной регистрации прав, - от одной тысячи пятисот до трех тысяч рублей. (В редакции  федеральных законов от 28.12.2013 № 430-ФЗ, от 30.11.2024 № 420-ФЗ)\n\n(Часть в редакции Федерального закона от 28.07.2012 № 133-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц органов государственной власти, органов местного самоуправления или органов государственных внебюджетных фондов Российской Федерации в размере от двадцати тысяч до двадцати пяти тысяч рублей либо дисквалификацию сроком на шесть месяцев; на работников многофункциональных центров, работников иных организаций, осуществляющих в соответствии с законодательством Российской Федерации функции многофункционального центра, работников публично-правовой компании, осуществляющей оказание государственных услуг в сфере государственного кадастрового учета и государственной регистрации прав, - от пяти тысяч до десяти тысяч рублей либо дисквалификацию сроком на шесть месяцев.\n\n(Дополнение частью - Федеральный закон от 30.11.2024 № 420-ФЗ)\n\nвлечет наложение административного штрафа в размере от двадцати тысяч до тридцати тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, органов местного самоуправления, осуществляющих исполнительно-распорядительные полномочия, или органов государственных внебюджетных фондов Российской Федерации в размере от десяти тысяч до пятнадцати тысяч рублей либо дисквалификацию сроком на шесть месяцев; на работников многофункциональных центров, работников иных организаций, осуществляющих в соответствии с законодательством Российской Федерации функции многофункционального центра, работников публично-правовой компании, осуществляющей оказание государственных услуг в сфере государственного кадастрового учета и государственной регистрации прав, - от трех тысяч до пяти тысяч рублей либо дисквалификацию сроком на шесть месяцев. (В редакции  федеральных законов от 28.12.2013 № 430-ФЗ, от 23.06.2020 № 184-ФЗ, от 30.11.2024 № 420-ФЗ)\n\n(Дополнение частью - Федеральный закон от 28.07.2012 № 133-ФЗ)\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей либо дисквалификацию на срок от шести месяцев до одного года.\n\n(Дополнение частью - Федеральный закон от 28.07.2012 № 133-ФЗ)\n\nПримечание. Положения настоящей статьи не распространяются на административные правонарушения, предусмотренные статьей 14.91 настоящего Кодекса.  (Дополнение примечанием - Федеральный закон от 13.07.2015 № 250-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 03.12.2011 № 383-ФЗ)","article_title":"Статья 5.63. Нарушение законодательства об организации предоставления государственных и муниципальных услуг","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2529c0c4c78584ddacbdafc55464a6b90aa716c1be2754c75e7135a28cad3dee"},{"code_id":"KoAP_RF","article_number":"5.631","version_date":"2001-12-30","article_text":"1. Нарушение установленных сроков согласования маршрутов тяжеловесного и (или) крупногабаритного транспортного средства или срока выдачи специального разрешения на движение по автомобильным дорогам тяжеловесного и (или) крупногабаритного транспортного средства либо необоснованный отказ в согласовании маршрутов тяжеловесного и (или) крупногабаритного транспортного средства или в выдаче специального разрешения на движение по автомобильным дорогам тяжеловесного и (или) крупногабаритного транспортного средства -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от ста тысяч до двухсот пятидесяти тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от тридцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от двухсот пятидесяти тысяч до пятисот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 13.07.2015 № 248-ФЗ)","article_title":"Статья 5.631. Нарушение требований законодательства, предусматривающих выдачу специальных разрешений на движение по автомобильным дорогам тяжеловесного и (или) крупногабаритного транспортного средства","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b5b3897fee7d31276741515da97c0d4dbedeec28ec0c51ae4668ea93e032007"},{"code_id":"KoAP_RF","article_number":"5.64","version_date":"2001-12-30","article_text":"1. Нарушение политической партией, ее региональным отделением или иным зарегистрированным структурным подразделением установленного законодательством Российской Федерации о политических партиях срока представления сведений о поступлении и расходовании средств политической партии, либо представление этих сведений в меньшем объеме, чем предусмотрено указанным законодательством, или с нарушением установленной формы, либо представление заведомо недостоверных сведений -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от двадцати тысяч до двадцати пяти тысяч рублей; на политическую партию, ее региональное отделение или иное зарегистрированное структурное подразделение - от пятидесяти тысяч до ста тысяч рублей.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятидесяти тысяч до ста тысяч рублей; на политическую партию, ее региональное отделение или иное зарегистрированное структурное подразделение - от ста тысяч до трехсот тысяч рублей.\n\n3. Нарушение политической партией установленного законодательством Российской Федерации о политических партиях срока представления сводного финансового отчета политической партии, либо представление этого отчета в меньшем объеме, чем предусмотрено указанным законодательством, или с нарушением установленной формы, либо указание в этом отчете заведомо недостоверных сведений -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до двадцати пяти тысяч рублей; на политическую партию - от пятидесяти тысяч до ста тысяч рублей.\n\n4. Повторное в течение следующего отчетного периода, установленного законодательством Российской Федерации о политических партиях, совершение административного правонарушения, предусмотренного частью 3 настоящей статьи, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятидесяти тысяч до ста тысяч рублей; на политическую партию - от двухсот тысяч до пятисот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 355-ФЗ)","article_title":"Статья 5.64. Нарушение порядка или срока представления сведений о поступлении и расходовании средств политической партии, сводного финансового отчета политической партии","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6a863f61ddd07772cd75e4e8cc366fc1bf76c5745aa17ddc98b3766aefea196"},{"code_id":"KoAP_RF","article_number":"5.65","version_date":"2001-12-30","article_text":"Использование политической партией или ее региональным отделением при финансировании своей деятельности, не связанной с участием в выборах и референдумах, денежных средств и иного имущества, полученных в качестве пожертвований от физического или юридического лица либо другого субъекта, которым законодательством Российской Федерации о политических партиях запрещено осуществлять пожертвования, либо полученных в размере, превышающем максимальный размер соответствующего пожертвования, либо перечисленных (переданных) с нарушением установленного указанным законодательством порядка, -\n\nвлечет наложение административного штрафа на политическую партию или ее региональное отделение в размере от ста тысяч до двухсот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 355-ФЗ)","article_title":"Статья 5.65. Незаконное использование политической партией денежных средств и иного имущества при финансировании своей деятельности, не связанной с участием в выборах и референдумах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a7bc517b70dfd059af1534fa4ce18992be15df2d8c5d052a8ae3247d2e50b84"},{"code_id":"KoAP_RF","article_number":"5.66","version_date":"2001-12-30","article_text":"1. Осуществление пожертвования политической партии или ее региональному отделению физическим или юридическим лицом либо другим субъектом, которым законодательством Российской Федерации о политических партиях запрещено осуществлять пожертвования, либо осуществление пожертвования с нарушением установленного указанным законодательством порядка его перечисления (передачи) политической партии или ее региональному отделению -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n2. Перечисление (передача) денежных средств и (или) иного имущества физическому или юридическому лицу для осуществления им пожертвования политической партии или ее региональному отделению, либо сбор денежных средств и (или) иного имущества в указанных целях, либо оказание содействия такому сбору -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n3. Осуществление пожертвования политической партии или ее региональному отделению физическим или юридическим лицом, получившим для осуществления пожертвования денежные средства и (или) иное имущество от другого лица, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до пятнадцати тысяч рублей; на должностных лиц - от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от двухсот тысяч до трехсот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 355-ФЗ)","article_title":"Статья 5.66. Незаконное финансирование деятельности политических партий, не связанной с участием в выборах и референдумах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c7eea850dea7dc9bc9f68a4d2bd79b68b90fffe2bde697fd2fa199cc7a9be1e"},{"code_id":"KoAP_RF","article_number":"5.67","version_date":"2001-12-30","article_text":"Нарушение установленного законодательством Российской Федерации о политических партиях срока возврата жертвователю (а в случае невозможности возврата - перечисления (передачи) в доход Российской Федерации) пожертвования (его части), перечисленного (переданного) политической партии или ее региональному отделению с нарушением установленного указанным законодательством порядка, -\n\nвлечет наложение административного штрафа в размере от ста тысяч до трехсот тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 355-ФЗ)","article_title":"Статья 5.67. Нарушение срока возврата жертвователю, перечисления (передачи) в доход Российской Федерации пожертвований политической партии","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b572eea9bcaaafe996984fbbabb0628217d924e3c941d8c8f3818b7a75e9feeb"},{"code_id":"KoAP_RF","article_number":"5.68","version_date":"2001-12-30","article_text":"1. Невыполнение установленных законодательством Российской Федерации о политических партиях требований об обязательном аудите годовой бухгалтерской (финансовой) отчетности и сводного финансового отчета политической партии -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пятидесяти тысяч до ста тысяч рублей; на политическую партию - от пятисот тысяч до одного миллиона рублей.\n\n2. Нарушение политической партией установленного законодательством Российской Федерации о политических партиях срока проведения обязательного аудита в отношении всех региональных отделений, иных зарегистрированных структурных подразделений политической партии -\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до сорока тысяч рублей; на политическую партию - от двухсот тысяч до четырехсот тысяч рублей.\n\n3. Нарушение политической партией установленного законодательством Российской Федерации о политических партиях срока представления экземпляра аудиторского заключения -\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от двадцати тысяч до двадцати пяти тысяч рублей; на политическую партию - от пятидесяти тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 355-ФЗ)","article_title":"Статья 5.68. Нарушение установленных законодательством Российской Федерации о политических партиях требований об обязательном аудите","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f446483a1d4d174abfd2ef02525858e57b6aafc1c09a7cd09a5028ff4593337"},{"code_id":"KoAP_RF","article_number":"5.69","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nВмешательство в осуществление избирательной комиссией, комиссией референдума полномочий, установленных законодательством о выборах и референдумах, повлекшее нарушение установленного законодательством о выборах и референдумах порядка работы избирательной комиссии, либо создание помех участию избирателей, участников референдума, участников общероссийского голосования в голосовании, если эти действия не содержат уголовно наказуемого деяния, - (В редакции Федерального закона от 01.04.2020 № 90-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до пяти тысяч рублей; на должностных лиц - от двадцати тысяч до пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 09.03.2016 № 66-ФЗ)\n\nГЛАВА 6. АДМИНИСТРАТИВНЫЕ ПРАВОНАРУШЕНИЯ, ПОСЯГАЮЩИЕ НА ЗДОРОВЬЕ, САНИТАРНО-ЭПИДЕМИОЛОГИЧЕСКОЕ БЛАГОПОЛУЧИЕ НАСЕЛЕНИЯ И ОБЩЕСТВЕННУЮ НРАВСТВЕННОСТЬ","article_title":"Статья 5.69. Вмешательство в осуществление избирательной комиссией, комиссией референдума полномочий, установленных законодательством о выборах и референдумах, либо создание помех участию избирателей, участников референдума, участников общероссийского голосования в голосовании","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa5c0635d273927b74476a5e27f7755373025a803d4047dce749ea756495c2a2"},{"code_id":"KoAP_RF","article_number":"5.7","version_date":"2001-12-30","article_text":"Отказ работодателя предоставить предусмотренный законом отпуск зарегистрированному кандидату, доверенному лицу зарегистрированного кандидата, избирательного объединения для проведения агитационной и иной предусмотренной законом деятельности, способствующей избранию зарегистрированного кандидата, списка кандидатов, а равно отказ работодателя освободить от работы в установленном законом порядке члена избирательной комиссии, комиссии референдума для участия в подготовке и проведении выборов, референдума - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.7. Отказ в предоставлении отпуска для участия в выборах, референдуме","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f832174cdac35c680810943c3aea089222df32dfd8de5dacb8e11e302b77f1c"},{"code_id":"KoAP_RF","article_number":"5.8","version_date":"2001-12-30","article_text":"Нарушение кандидатом, избирательным объединением, членом или уполномоченным представителем инициативной группы по проведению референдума, иной группы участников референдума, иным лицом, уполномоченным выступать от имени кандидата, избирательного объединения или привлеченным указанными лицами к проведению предвыборной агитации, либо лицом, замещающим государственную должность или выборную муниципальную должность, предусмотренных законодательством о выборах и референдумах порядка и условий проведения предвыборной агитации, агитации по вопросам референдума в средствах массовой информации - (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 09.03.2016 № 66-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч пятисот рублей; на должностных лиц - от двух тысяч до пяти тысяч рублей; на избирательные объединения, на иных юридических лиц - от двадцати тысяч до ста тысяч рублей. (В редакции федеральных законов от 21.07.2005 № 93-ФЗ; от 22.06.2007 № 116-ФЗ)\n\nПримечание. (Примечание утратило силу - Федеральный закон от 21.07.2005 № 93-ФЗ)\n\n(Статья в редакции Федерального закона от 04.07.2003 № 94-ФЗ)","article_title":"Статья 5.8. Нарушение предусмотренных законодательством о выборах и референдумах порядка и условий проведения предвыборной агитации, агитации по вопросам референдума на каналах организаций, осуществляющих теле- и (или) радиовещание, и в периодических печатных изданиях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc82bb53d20c2bab3f8e164a98fb32408f11895f35dc0efa5efaf46e8c6da6f6"},{"code_id":"KoAP_RF","article_number":"5.9","version_date":"2001-12-30","article_text":"Нарушение предусмотренных законодательством о выборах и референдумах условий рекламы предпринимательской и иной деятельности кандидатов, зарегистрированных кандидатов, избирательных объединений, иных лиц и организаций, на рекламирование предпринимательской и иной деятельности которых распространяются требования и ограничения, предусмотренные законодательством о выборах и референдумах, - (В редакции Федерального закона от 21.07.2005 № 93-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 5.9. Нарушение в ходе избирательной кампании условий рекламы предпринимательской и иной деятельности","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe847717c76c1e543b0205fc9bed90e22e7d1b36e1d1eb0baafd3ac4d1267a73"},{"code_id":"KoAP_RF","article_number":"6.1","version_date":"2001-12-30","article_text":"Сокрытие лицом, больным ВИЧ-инфекцией, венерическим заболеванием, источника заражения, а также лиц, имевших с указанным лицом контакты, создающие опасность заражения этими заболеваниями, -\n\nвлечет наложение административного штрафа в размере от пятисот до одной тысячи рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 6.1. Сокрытие источника заражения ВИЧ-инфекцией, венерической болезнью и контактов, создающих опасность заражения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff06b65e45e1f145ea31e64ae68a6ce97c2038d859468906ed255ad1520910c5"},{"code_id":"KoAP_RF","article_number":"6.10","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 03.02.2015 № 7-ФЗ)\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до трех тысяч рублей.\n\nвлекут наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей.\n\n(Статья в редакции Федерального закона от 21.12.2013 № 365-ФЗ)","article_title":"Статья 6.10. Вовлечение несовершеннолетнего в употребление алкогольной и спиртосодержащей продукции, новых потенциально опасных психоактивных веществ или одурманивающих веществ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1e240f84c018534d7e9a3bd599e381e2b71224f83a2e5ecc24e66f7a4d96fb8"},{"code_id":"KoAP_RF","article_number":"6.11","version_date":"2001-12-30","article_text":"Занятие проституцией -\n\nвлечет наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 6.11. Занятие проституцией","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4d92a4a250f404123302def839808d794c8038ec46ac8ef8f4e4eb5029fdd59"},{"code_id":"KoAP_RF","article_number":"6.12","version_date":"2001-12-30","article_text":"Получение дохода от занятия проституцией, если этот доход связан с занятием другого лица проституцией, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до двух тысяч пятисот рублей или административный арест на срок от десяти до пятнадцати суток.  (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 6.12. Получение дохода от занятия проституцией, если этот доход связан с занятием другого лица проституцией","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6550fb6b2f8103fdac3cab7a7b8f7ff706598dc59cb036de2fa22e92f7ccc9f"},{"code_id":"KoAP_RF","article_number":"6.13","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 19.05.2010 № 87-ФЗ; от 03.02.2015 № 7-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от четырех тысяч до пяти тысяч рублей с конфискацией рекламной продукции и оборудования, использованного для ее изготовления; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от сорока тысяч до пятидесяти тысяч рублей с конфискацией рекламной продукции и оборудования, использованного для ее изготовления либо административное приостановление деятельности на срок до девяноста суток с конфискацией рекламной продукции и оборудования, использованного для ее изготовления; на юридических лиц - от восьмисот тысяч до одного миллиона рублей с конфискацией рекламной продукции и оборудования, использованного для ее изготовления либо административное приостановление деятельности на срок до девяноста суток с конфискацией рекламной продукции и оборудования, использованного для ее изготовления. (В редакции федеральных законов от 09.05.2005 № 45-ФЗ; от 22.06.2007 № 116-ФЗ; от 28.12.2010 № 417-ФЗ)\n\n11. Пропаганда наркотических средств, психотропных веществ или их прекурсоров, растений, содержащих наркотические средства, психотропные вещества или их прекурсоры, их частей, содержащих наркотические средства, психотропные вещества или их прекурсоры, либо новых потенциально опасных психоактивных веществ с использованием информационно-телекоммуникационной сети \"Интернет\" -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до тридцати тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до ста тысяч рублей либо административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от одного миллиона до одного миллиона пятисот тысяч рублей либо административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение частью - Федеральный закон от 30.12.2020 № 512-ФЗ)\n\nвлекут наложение административного штрафа в размере от четырех тысяч до тридцати тысяч рублей с административным выдворением за пределы Российской Федерации или без такового либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации или без такового.\n\n(Дополнение частью - Федеральный закон от 28.12.2010 № 417-ФЗ) (В редакции Федерального закона от 30.12.2020 № 512-ФЗ)\n\nПримечание. Не является административным правонарушением распространение в специализированных изданиях, рассчитанных на медицинских и фармацевтических работников, сведений о разрешенных к применению в медицинских целях наркотических средствах, психотропных веществах и их прекурсорах.","article_title":"Статья 6.13. Пропаганда наркотических средств, психотропных веществ или их прекурсоров, растений, содержащих наркотические средства или психотропные вещества либо их прекурсоры, и их частей, содержащих наркотические средства или психотропные вещества либо их прекурсоры, новых потенциально опасных психоактивных веществ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"985fb3675eea92faba4fa64c2a002d4ef4952f89265a10121ada67869a1ee942"},{"code_id":"KoAP_RF","article_number":"6.131","version_date":"2001-12-30","article_text":"Пропаганда, в том числе посредством информационно-телекоммуникационной сети \"Интернет\", использования (потребления) закиси азота либо распространение информации о реализации (сбыте) закиси азота не в целях производства пищевой продукции, продовольственных товаров или продуктов питания либо не для медицинского, промышленного или технического применения -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до двух тысяч рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до двадцати тысяч рублей либо административное приостановление деятельности на срок до тридцати суток; на юридических лиц - от пятидесяти тысяч до ста пятидесяти тысяч рублей либо административное приостановление деятельности на срок до тридцати суток.\n\n(Дополнение статьей - Федеральный закон от 04.02.2021 № 4-ФЗ)","article_title":"Статья 6.131. Пропаганда закиси азота","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f4a91a01c1d59a59d0d81cf5c1ba8b4186c4ee048d3d77287b6aba987ba9ef2"},{"code_id":"KoAP_RF","article_number":"6.14","version_date":"2001-12-30","article_text":"(Статья утратила силу - Федеральный закон от 18.07.2011 № 237-ФЗ)","article_title":"Статья 6.14. .","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fc262a3d96337498de00a86d6a8c309aa996ed921052150e9612093e5a3f0a77"},{"code_id":"KoAP_RF","article_number":"6.15","version_date":"2001-12-30","article_text":"ихотропных веществ\n\n(Наименование в редакции Федерального закона от 28.06.2009 № 122-ФЗ)\n\nНарушение юридическим лицом правил производства, изготовления, переработки, хранения, учета, отпуска, реализации, продажи, распределения, перевозки, пересылки, приобретения, использования, ввоза, вывоза либо уничтожения инструментов или оборудования, используемых для изготовления наркотических средств или психотропных веществ, -   (В редакции Федерального закона от 28.06.2009 № 122-ФЗ)\n\nвлечет наложение административного штрафа на юридических лиц в размере от пятидесяти тысяч до ста тысяч рублей с конфискацией инструментов или оборудования, используемых для изготовления наркотических средств или психотропных веществ, или без таковой либо административное приостановление деятельности на срок до девяноста суток с конфискацией инструментов или оборудования, используемых для изготовления наркотических средств или психотропных веществ, или без таковой. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 28.06.2009 № 122-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 09.05.2005 № 45-ФЗ)","article_title":"Статья 6.15. Нарушение правил оборота инструментов или оборудования, используемых для изготовления наркотических средств или пс","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f50ffa4e98e27712139d2cd5c48a19301dc194aa28dc87001a0abdd32c62f50"},{"code_id":"KoAP_RF","article_number":"6.16","version_date":"2001-12-30","article_text":"1. Нарушение правил производства, изготовления, переработки, хранения, учета, отпуска, реализации, распределения, перевозки, приобретения, использования, ввоза, вывоза либо уничтожения наркотических средств, психотропных веществ и включенных в список I и таблицу I списка IV Перечня наркотических средств, психотропных веществ и их прекурсоров, подлежащих контролю в Российской Федерации, прекурсоров наркотических средств или психотропных веществ либо хранения, учета, реализации, перевозки, приобретения, использования, ввоза, вывоза или уничтожения растений, содержащих наркотические средства или психотропные вещества либо их прекурсоры, и их частей, содержащих наркотические средства или психотропные вещества либо их прекурсоры, либо непредставление в государственный орган предусмотренной законом отчетности о деятельности, связанной с их оборотом, несвоевременное представление такой отчетности или представление такой отчетности в неполном объеме или в искаженном виде -\n\nвлечет наложение административного штрафа на юридических лиц в размере от двухсот тысяч до четырехсот тысяч рублей с конфискацией наркотических средств, психотропных веществ либо их прекурсоров или без таковой либо административное приостановление деятельности на срок до девяноста суток с конфискацией наркотических средств, психотропных веществ либо их прекурсоров или без таковой.\n\n2. Те же действия, совершенные в отношении прекурсоров наркотических средств или психотропных веществ, включенных в таблицу II списка IV Перечня наркотических средств, психотропных веществ и их прекурсоров, подлежащих контролю в Российской Федерации, -\n\nвлекут наложение административного штрафа на юридических лиц в размере от ста тысяч до двухсот тысяч рублей с конфискацией прекурсоров наркотических средств или психотропных веществ или без таковой либо административное приостановление деятельности на срок до девяноста суток с конфискацией прекурсоров наркотических средств или психотропных веществ или без таковой.\n\n3. Те же действия, совершенные в отношении прекурсоров наркотических средств или психотропных веществ, включенных в таблицу III списка IV Перечня наркотических средств, психотропных веществ и их прекурсоров, подлежащих контролю в Российской Федерации, -\n\nвлекут наложение административного штрафа на юридических лиц в размере от пятидесяти тысяч до ста тысяч рублей с конфискацией прекурсоров наркотических средств или психотропных веществ или без таковой.\n\nПримечание. За административные правонарушения, предусмотренные настоящей статьей, в части нарушения правил оборота прекурсоров наркотических средств или психотропных веществ, включенных в список IV Перечня наркотических средств, психотропных веществ и их прекурсоров, подлежащих контролю в Российской Федерации, лица, осуществляющие предпринимательскую деятельность без образования юридического лица, несут административную ответственность как юридические лица.\n\n(Дополнение статьей - Федеральный закон от 28.06.2009 № 122-ФЗ) (В редакции Федерального закона от 02.10.2012 № 158-ФЗ)","article_title":"Статья 6.16. Нарушение правил оборота наркотических средств, психотропных веществ и их прекурсоров либо хранения, учета, реализации, перевозки, приобретения, использования, ввоза, вывоза или уничтожения растений, содержащих наркотические средства или психотропные вещества либо их прекурсоры, и их частей, содержащих наркотические средства или психотропные вещества либо их прекурсоры","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"751978d0e1ee9384cd56f92818412d3029bf3f11449df5b1b14a941c78adbf1e"},{"code_id":"KoAP_RF","article_number":"6.161","version_date":"2001-12-30","article_text":"1. Незаконные приобретение, хранение, перевозка, производство, сбыт или пересылка прекурсоров наркотических средств или психотропных веществ, а также незаконные приобретение, хранение, перевозка, сбыт или пересылка растений, содержащих прекурсоры наркотических средств или психотропных веществ, либо их частей, содержащих прекурсоры наркотических средств или психотропных веществ, если эти действия не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до пятнадцати суток.\n\n2. Те же действия, совершенные иностранным гражданином или лицом без гражданства, -\n\nвлекут наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\nПримечания:\n\n1. Лицо, совершившее административное правонарушение, предусмотренное настоящей статьей, добровольно сдавшее приобретенные прекурсоры наркотических средств или психотропных веществ, растения, содержащие прекурсоры наркотических средств или психотропных веществ, либо их части, содержащие прекурсоры наркотических средств или психотропных веществ, освобождается от административной ответственности за данное административное правонарушение. Не может признаваться добровольной сдачей прекурсоров наркотических средств или психотропных веществ, растений, содержащих прекурсоры наркотических средств или психотропных веществ, либо их частей, содержащих прекурсоры наркотических средств или психотропных веществ, их изъятие после возбуждения дела об административном правонарушении.\n\n2. Действие настоящей статьи распространяется на оборот прекурсоров, включенных в список I и таблицу I списка IV Перечня наркотических средств, психотропных веществ и их прекурсоров, подлежащих контролю в Российской Федерации, утверждаемого Правительством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 01.03.2012 № 18-ФЗ)","article_title":"Статья 6.161. Незаконные приобретение, хранение, перевозка, производство, сбыт или пересылка прекурсоров наркотических средств или психотропных веществ, а также незаконные приобретение, хранение, перевозка, сбыт или пересылка растений, содержащих прекурсоры наркотических средств или психотропных веществ, либо их частей, содержащих прекурсоры наркотических средств или психотропных веществ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c184f228dcdeb46abc0ba15e64bbbc09080be223bae00017967247b95224f2ce"},{"code_id":"KoAP_RF","article_number":"6.17","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей с конфискацией предмета административного правонарушения; на должностных лиц - от пяти тысяч до десяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до десяти тысяч рублей с конфискацией предмета административного правонарушения или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двадцати тысяч до пятидесяти тысяч рублей с конфискацией предмета административного правонарушения или административное приостановление деятельности на срок до девяноста суток. (В редакции Федерального закона от 29.06.2013 № 135-ФЗ)\n\nвлечет наложение административного штрафа на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, в размере от пяти тысяч до десяти тысяч рублей; на юридических лиц - от двадцати тысяч до пятидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до полутора тысяч рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 21.07.2011 № 252-ФЗ)","article_title":"Статья 6.17. Нарушение законодательства Российской Федерации о защите детей от информации, причиняющей вред их здоровью и (или) развитию","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b191c19cf639dcdecde4f54d7514a1d0001f5cc521042f5cd991d103fc01e019"},{"code_id":"KoAP_RF","article_number":"6.18","version_date":"2001-12-30","article_text":"1. Умышленное нарушение спортсменом установленных законодательством о физической культуре и спорте требований о предотвращении допинга в спорте и борьбе с ним, выразившееся в использовании или попытке использования спортсменом запрещенной субстанции и (или) запрещенного метода (за исключением случаев, если в соответствии с законодательством о физической культуре и спорте осуществление указанных действий не является нарушением антидопинговых правил, а также случаев, предусмотренных частью 2 настоящей статьи и статьями 6.9, 20.20 и 20.22 настоящего Кодекса), -\n\nвлечет наложение административного штрафа в размере от тридцати тысяч до пятидесяти тысяч рублей.\n\n2. Распространение спортсменом, тренером, специалистом по спортивной медицине или иным специалистом в области физической культуры и спорта запрещенной субстанции и (или) запрещенного метода (за исключением случаев, если в соответствии с законодательством о физической культуре и спорте осуществление указанных действий не является нарушением антидопинговых правил, а также случаев, предусмотренных статьями 6.8, 6.16 и 6.161 настоящего Кодекса), если эти действия не содержат уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от сорока тысяч до восьмидесяти тысяч рублей.\n\nПримечание. Под запрещенной субстанцией и (или) запрещенным методом в настоящей статье понимаются субстанция и (или) метод, включенные в перечни субстанций и (или) методов, запрещенных для использования в спорте, утвержденные федеральным органом исполнительной власти, осуществляющим функции по проведению государственной политики, нормативно-правовому регулированию, оказанию государственных услуг и управлению государственным имуществом в сфере физической культуры и спорта.\n\n(Дополнение статьей - Федеральный закон от 06.12.2011 № 413-ФЗ) (В редакции Федерального закона от 01.05.2019 № 96-ФЗ)","article_title":"Статья 6.18. Нарушение установленных законодательством о физической культуре и спорте требований о предотвращении допинга в спорте и борьбе с ним","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1528c2ebf108ff8ae7546f77edd779312122278f57e194c790c1b5cde5d4d732"},{"code_id":"KoAP_RF","article_number":"6.19","version_date":"2001-12-30","article_text":"Создание юридическим лицом условий для торговли детьми и (или) эксплуатации детей, выразившееся в предоставлении помещений, транспортных средств или иных материальных средств, в создании бытовых условий для торговли детьми и (или) эксплуатации детей, в оказании услуг, содействующих торговле детьми и (или) эксплуатации детей, либо в финансировании торговли детьми и (или) эксплуатации детей, -\n\nвлечет наложение административного штрафа на юридических лиц в размере от одного миллиона до пяти миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\nПримечания:\n\n1. За административное правонарушение, предусмотренное настоящей статьей, юридическое лицо несет ответственность в случае, если это правонарушение совершено от имени или в интересах юридического лица лицом, выполняющим управленческие функции в данной организации.\n\n2. В настоящей статье под лицом, выполняющим управленческие функции в организации, понимается лицо, выполняющее функции единоличного исполнительного органа, члена совета директоров или иного коллегиального исполнительного органа, а также лицо, постоянно, временно либо по специальному полномочию выполняющее организационно-распорядительные или административно-хозяйственные функции в данной организации.\n\n(Дополнение статьей - Федеральный закон от 05.04.2013 № 58-ФЗ)","article_title":"Статья 6.19. Создание юридическим лицом условий для торговли детьми и (или) эксплуатации детей","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6b5135350dc41e75225b1c5c6e2a3a48b4b0271ee5de47a826a751ae74d8b5d"},{"code_id":"KoAP_RF","article_number":"6.2","version_date":"2001-12-30","article_text":"Занятие народной медициной без получения разрешения, установленного законом, -\n\nвлечет наложение административного штрафа в размере от двух тысяч до четырех тысяч рублей.\n\n(Статья в редакции Федерального закона от 25.11.2013 № 317-ФЗ)","article_title":"Статья 6.2. Незаконное занятие народной медициной","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d70b65d52df7a67192a805af1c49f9cb9dbb52ac8a5217c0e71a5b64e3074b2"},{"code_id":"KoAP_RF","article_number":"6.20","version_date":"2001-12-30","article_text":"Изготовление, приобретение, хранение, перевозка, распространение, публичная демонстрация либо рекламирование юридическим лицом материалов или предметов с порнографическими изображениями несовершеннолетних -\n\nвлечет наложение административного штрафа на юридических лиц в размере от одного миллиона до пяти миллионов рублей с конфискацией материалов или предметов с порнографическими изображениями несовершеннолетних и оборудования, использованного для изготовления таких материалов или предметов, либо административное приостановление деятельности на срок до девяноста суток с конфискацией материалов или предметов с порнографическими изображениями несовершеннолетних и оборудования, использованного для изготовления таких материалов или предметов.\n\nПримечания:\n\n1. За административное правонарушение, предусмотренное настоящей статьей, юридическое лицо несет ответственность в случае, если это правонарушение совершено от имени или в интересах юридического лица лицом, выполняющим управленческие функции в данной организации.\n\n2. В настоящей статье под лицом, выполняющим управленческие функции в организации, понимается лицо, выполняющее функции единоличного исполнительного органа, члена совета директоров или иного коллегиального исполнительного органа, а также лицо, постоянно, временно либо по специальному полномочию выполняющее организационно-распорядительные или административно-хозяйственные функции в данной организации.\n\n(Дополнение статьей - Федеральный закон от 05.04.2013 № 58-ФЗ)","article_title":"Статья 6.20. Изготовление юридическим лицом материалов или предметов с порнографическими изображениями несовершеннолетних и оборот таких материалов или предметов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"91c65c695a76f663cbba5967b189bafcb3fe4a361b7e51c85826ff741f0db29a"},{"code_id":"KoAP_RF","article_number":"6.21","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 23.11.2024 № 401-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятидесяти тысяч до ста тысяч рублей; на должностных лиц - от ста тысяч до двухсот тысяч рублей; на юридических лиц - от восьмисот тысяч до одного миллиона рублей либо административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа на граждан в размере от ста тысяч до двухсот тысяч рублей; на должностных лиц - от двухсот тысяч до четырехсот тысяч рублей; на юридических лиц - от одного миллиона до двух миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа на граждан в размере от ста тысяч до двухсот тысяч рублей; на должностных лиц - от двухсот тысяч до четырехсот тысяч рублей; на юридических лиц - от одного миллиона до четырех миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа на граждан в размере от двухсот тысяч до четырехсот тысяч рублей; на должностных лиц - от четырехсот тысяч до восьмисот тысяч рублей; на юридических лиц - от двух миллионов до пяти миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\nвлекут наложение административного штрафа в размере от пятидесяти тысяч до ста тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\nвлекут наложение административного штрафа в размере от ста тысяч до двухсот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\nвлекут наложение административного штрафа в размере от ста тысяч до двухсот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Ро\n\nссийской Федерации.\n\nвлекут наложение административного штрафа в размере от двухсот тысяч до четырехсот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\nПримечание. Не являются административным правонарушением распространение информации о монашестве и монашеском образе жизни, соблюдении обета безбрачия (целибата) и связанном с ними отказе от деторождения и (или) совершение публичных действий, направленных на формирование привлекательности монашества и монашеского образа жизни, соблюдения обета безбрачия (целибата) и связанного с ними отказа от деторождения, если такие информация и публичные действия основаны на внутренних установлениях централизованных религиозных организаций или религиозных организаций, входящих в их структуру. (Дополнение примечанием - Федеральный закон от 23.11.2024 № 401-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.06.2013 № 135-ФЗ) (В редакции Федерального закона от 05.12.2022 № 479-ФЗ)","article_title":"Статья 6.21. Пропаганда нетрадиционных сексуальных отношенийи (или) предпочтений, смены пола, отказа от деторождения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecc12ce96678c917792b33bff3b60b547f5c0cdb96aa3530c4ad73460d1d5823"},{"code_id":"KoAP_RF","article_number":"6.211","version_date":"2001-12-30","article_text":"1. Пропаганда педофилии, выразившаяся в распространении информации, направленной на обоснование и (или) оправдание педофилии или формирование привлекательности педофилии, либо навязывание информации о педофилии, вызывающей интерес к педофилии, за исключением случаев, предусмотренных статьей 6.20 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на граждан в размере от двухсот тысяч до четырехсот тысяч рублей; на должностных лиц - от четырехсот тысяч до восьмисот тысяч рублей; на юридических лиц - от одного миллиона до четырех миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\n2. Действия, предусмотренные частью 1 настоящей статьи, совершенные с применением средств массовой информации и (или) информационно-телекоммуникационных сетей (в том числе сети \"Интернет\"), если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от четырехсот тысяч до восьмисот тысяч рублей; на должностных лиц - от восьмисот тысяч до двух миллионов рублей; на юридических лиц - от четырех миллионов до десяти миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия, предусмотренные частью 1 настоящей статьи, совершенные иностранным гражданином или лицом без гражданства, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа в размере от двухсот тысяч до четырехсот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n4. Действия, предусмотренные частью 1 настоящей статьи, совершенные иностранным гражданином или лицом без гражданства с применением средств массовой информации и (или) информационно-телекоммуникационных сетей (в том числе сети \"Интернет\"), если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа в размере от четырехсот тысяч до восьмисот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 05.12.2022 № 479-ФЗ)","article_title":"Статья 6.211. Пропаганда педофилии","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d85c87bc56498a2a921afed5228e6f8546cb01b5e4f89d0ef13b32c3c0b868ac"},{"code_id":"KoAP_RF","article_number":"6.212","version_date":"2001-12-30","article_text":"1. Распространение среди несовершеннолетних информации, демонстрирующей нетрадиционные сексуальные отношения и (или) предпочтения, в том числе описание, изображение нетрадиционных сексуальных отношений и (или) предпочтений, либо способной вызвать у несовершеннолетних желание сменить пол, за исключением случаев, предусмотренных частью 2 статьи 6.21 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на граждан в размере от пятидесяти тысяч до ста тысяч рублей; на должностных лиц - от ста тысяч до двухсот тысяч рублей; на юридических лиц - от восьмисот тысяч до одного миллиона рублей либо административное приостановление деятельности на срок до девяноста суток.\n\n2. Действия, предусмотренные частью 1 настоящей статьи, совершенные с применением средств массовой информации и (или) информационно-телекоммуникационных сетей (в том числе сети \"Интернет\"), за исключением случаев, предусмотренных частью 4 статьи 6.21 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от ста тысяч до двухсот тысяч рублей; на должностных лиц - от двухсот тысяч до четырехсот тысяч рублей; на юридических лиц - от одного миллиона до четырех миллионов рублей либо административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия, предусмотренные частью 1 настоящей статьи, совершенные иностранным гражданином или лицом без гражданства, за исключением случаев, предусмотренных частью 6 статьи 6.21 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа в размере от пятидесяти тысяч до ста тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n4. Действия, предусмотренные частью 1 настоящей статьи, совершенные иностранным гражданином или лицом без гражданства с применением средств массовой информации и (или) информационно-телекоммуникационных сетей (в том числе сети \"Интернет\"), за исключением случаев, предусмотренных частью 8 статьи 6.21 настоящего Кодекса, если эти действия не содержат признаков уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа в размере от ста тысяч до двухсот тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 05.12.2022 № 479-ФЗ)","article_title":"Статья 6.212. Распространение среди несовершеннолетних информации, демонстрирующей нетрадиционные сексуальные отношения и (или) предпочтения либо способной вызвать у несовершеннолетних желание сменить пол","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4fbd6ea931c0629ad871a6d4305ca627e972f7548260eb754d204ad521169e4"},{"code_id":"KoAP_RF","article_number":"6.22","version_date":"2001-12-30","article_text":"Невключение организатором официального спортивного соревнования, не являющимся спортивной федерацией, в положение (регламент) об официальном спортивном соревновании требований о запрете на противоправное влияние на результат официального спортивного соревнования, а также о запрете на участие спортсменов, спортивных судей, тренеров, руководителей спортивных команд и других участников официального спортивного соревнования в азартных играх в букмекерских конторах и тотализаторах путем заключения пари на официальное спортивное соревнование -\n\nвлечет наложение административного штрафа на граждан в размере от тридцати тысяч до пятидесяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста тысяч рублей; на юридических лиц - от восьмисот тысяч до одного миллиона рублей.\n\nПримечания:\n\n1. За административное правонарушение, предусмотренное настоящей статьей, организатор официального спортивного соревнования несет ответственность в случае, если выявлены факты противоправного влияния на результат этого соревнования.\n\n2. Требование о запрете на участие в азартных играх в букмекерских конторах и тотализаторах путем заключения пари на официальные спортивные соревнования распространяется на спортсменов в отношении официальных спортивных соревнований по виду или видам спорта, по которым они участвуют в соответствующих официальных спортивных соревнованиях, на спортивных судей в отношении официальных спортивных соревнований по виду или видам спорта, по которым они обеспечивают соблюдение правил вида или видов спорта и положений (регламентов) о соответствующих официальных спортивных соревнованиях, на тренеров в отношении официальных спортивных соревнований по виду или видам спорта, по которым они проводят тренировочные мероприятия и осуществляют руководство состязательной деятельностью спортсменов, участвующих в соответствующих официальных спортивных соревнованиях, на руководителей спортивных команд в отношении официальных спортивных соревнований по виду или видам спорта, по которым руководимые ими спортивные команды участвуют в соответствующих официальных спортивных соревнованиях, на других участников официальных спортивных соревнований в отношении официальных спортивных соревнований по виду или видам спорта, по которым они участвуют в соответствующих официальных спортивных соревнованиях.\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 198-ФЗ)","article_title":"Статья 6.22. Нарушение установленных законодательством о физической культуре и спорте требований к положениям (регламентам) об официальных спортивных соревнованиях","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79932bae885322b567d810fe6c5e8a95c8b3371032bbf89bdf3e65e80169d918"},{"code_id":"KoAP_RF","article_number":"6.23","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 31.07.2020 № 303-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до пяти тысяч рублей. (В редакции  Федерального закона от 28.04.2023 № 175-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей. (В редакции  Федерального закона от 28.04.2023 № 175-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 21.10.2013 № 274-ФЗ)","article_title":"Статья 6.23. Вовлечение несовершеннолетнего в процесс потребления табака или потребления никотинсодержащей продукции","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"074c7d37996fa8ffd767cf712529009ab6d2c544856f9e7bd73cbf7289ae7d6d"},{"code_id":"KoAP_RF","article_number":"6.24","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 31.07.2020 № 303-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи пятисот рублей.\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 21.10.2013 № 274-ФЗ)","article_title":"Статья 6.24. Нарушение установленного федеральным законом запрета курения табака, потребления никотинсодержащей продукции или использования кальянов на отдельных территориях, в помещениях и на объектах","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e47e20f02d8cdf7c98a248743f8a9f35514055ee4055b5eaa4492ed9b6ee2f9a"},{"code_id":"KoAP_RF","article_number":"6.25","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 31.07.2020 № 303-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от тридцати тысяч до шестидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от пятидесяти тысяч до восьмидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на индивидуальных предпринимателей в размере от тридцати тысяч до сорока тысяч рублей; на юридических лиц - от шестидесяти тысяч до девяноста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 21.10.2013 № 274-ФЗ)","article_title":"Статья 6.25. Несоблюдение требований к знаку о запрете курения табака, потребления никотинсодержащей продукции или использования кальянов, к выделению и оснащению специальных мест для курения табака, потребления никотинсодержащей продукции или использования кальянов либо неисполнение обязанностей по контролю за соблюдением норм законодательства в сфере охраны здоровья граждан от воздействия окружающего табачного дыма, последствий потребления табака или потребления никотинсодержащей продукции","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a72353cad498837d0179c9cb6e8e7f80c02e5010370ff41dece3f2a86be64c0e"},{"code_id":"KoAP_RF","article_number":"6.26","version_date":"2001-12-30","article_text":"1. Организация публичного исполнения произведения литературы, искусства или народного творчества, содержащего нецензурную брань, посредством проведения театрально-зрелищного, культурно-просветительного или зрелищно-развлекательного мероприятия -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от четырех тысяч до пяти тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч пятисот до пяти тысяч рублей; на должностных лиц - от пяти тысяч до двадцати тысяч рублей или дисквалификацию на срок от шести месяцев до одного года; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 101-ФЗ)","article_title":"Статья 6.26. Организация публичного исполнения произведения литературы, искусства или народного творчества, содержащего нецензурную брань, посредством проведения театрально-зрелищного, культурно-просветительного или зрелищно-развлекательного мероприятия","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7da852c93f4b399e9aa759e35891de92fa04bbb8064bc84c36afeb8478913f76"},{"code_id":"KoAP_RF","article_number":"6.27","version_date":"2001-12-30","article_text":"1. Распространение экземпляров аудиовизуальной продукции и фонограмм на любых видах носителей, экземпляров печатной продукции (за исключением продукции средств массовой информации), содержащих нецензурную брань, без специальной упаковки и текстового предупреждения в виде словосочетания \"содержит нецензурную брань\" -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей; на должностных лиц - от четырех тысяч до пяти тысяч рублей; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей.\n\n2. Повторное совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч пятисот до пяти тысяч рублей; на должностных лиц - от пяти тысяч до двадцати тысяч рублей или дисквалификацию на срок от шести месяцев до одного года; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 101-ФЗ)","article_title":"Статья 6.27. Распространение экземпляров аудиовизуальной продукции и фонограмм на любых видах носителей, экземпляров печатной продукции, содержащих нецензурную брань, без специальной упаковки и текстового предупреждения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"505c37f7a28a0e033f467c6607ec2ed2aa3b8a781ae651637f5c6427eff62a48"},{"code_id":"KoAP_RF","article_number":"6.28","version_date":"2001-12-30","article_text":"Нарушение установленных правил в сфере обращения медицинских изделий, если эти действия не содержат признаков уголовно наказуемого деяния, -   (В редакции Федерального закона от 31.12.2014 № 532-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до четырех тысяч рублей; на должностных лиц - от пяти тысяч до десяти тысяч рублей; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 25.11.2013 № 317-ФЗ)","article_title":"Статья 6.28. Нарушение установленных правил в сфере обращения медицинских изделий","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0becc990c42b1aa3ff53b1da6180a10284cdc06c6da43e440242c13eaa03f483"},{"code_id":"KoAP_RF","article_number":"6.29","version_date":"2001-12-30","article_text":"1. Непредставление медицинским работником информации о возникновении конфликта интересов руководителю медицинской организации, в которой он работает, либо фармацевтическим работником информации о возникновении конфликта интересов руководителю аптечной организации, в которой он работает, -\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.\n\n2. Непредставление или несвоевременное представление руководителем медицинской организации уведомления о возникновении конфликта интересов медицинского работника или руководителем аптечной организации уведомления о возникновении конфликта интересов фармацевтического работника в уполномоченный федеральный орган исполнительной власти -\n\nвлечет наложение административного штрафа в размере от пяти тысяч до десяти тысяч рублей.\n\n3. Непредставление индивидуальным предпринимателем, осуществляющим медицинскую деятельность или фармацевтическую деятельность, информации о возникновении конфликта интересов в уполномоченный федеральный орган исполнительной власти -\n\nвлечет наложение административного штрафа в размере от трех тысяч до пяти тысяч рублей.\n\n4. Совершение административного правонарушения, предусмотренного частями 1, 2 и 3 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, -\n\nвлечет наложение административного штрафа в размере от десяти тысяч до двадцати тысяч рублей либо дисквалификацию сроком на шесть месяцев. (В редакции Федерального закона от 23.06.2020 № 184-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2013 № 317-ФЗ)","article_title":"Статья 6.29. Невыполнение обязанностей о представлении информации о конфликте интересов при осуществлении медицинской деятельности и фармацевтической деятельности","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b896705d7576a229195f2841f82612eed73dc8a169a195b6fbddbe5e09f6e223"},{"code_id":"KoAP_RF","article_number":"6.3","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 28.12.2009 № 380-ФЗ; от 18.07.2011 № 237-ФЗ)\n\nвлечет предупреждение или наложение административного штрафа на граждан в размере от ста до пятисот рублей; на должностных лиц - от пятисот до одной тысячи рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятисот до одной тысячи рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от десяти тысяч до двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции федеральных законов от 09.05.2005 № 45-ФЗ; от 22.06.2007 № 116-ФЗ)\n\nльный государственный санитарно-эпидемиологический надзор, о проведении санитарно-противоэпидемических (профилактических) мероприятий -\n\nвлекут наложение административного штрафа на граждан в размере от пятнадцати тысяч до сорока тысяч рублей; на должностных лиц - от пятидесяти тысяч до ста пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до ста пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот тысяч до пятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение частью - Федеральный закон от 01.04.2020 № 99-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от ста пятидесяти тысяч до трехсот тысяч рублей; на должностных лиц - от трехсот тысяч до пятисот тысяч рублей или дисквалификацию на срок от одного года до трех лет; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятисот тысяч до одного миллиона рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до одного миллиона рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение частью - Федеральный закон от 01.04.2020 № 99-ФЗ)","article_title":"Статья 6.3. Нарушение законодательства в области обеспечения санитарно-эпидемиологического благополучия населения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c7cf36f54e1996b2b7ea409908832fd2e8a6fe397e0cfe8f096635eb136926f1"},{"code_id":"KoAP_RF","article_number":"6.30","version_date":"2001-12-30","article_text":"1. Невыполнение медицинской организацией обязанности об информировании граждан о возможности получения медицинской помощи в рамках программы государственных гарантий бесплатного оказания гражданам медици\n\nнской помощи и территориальных программ государственных гарантий бесплатного оказания гражданам медицинской помощи -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до семи тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей.\n\n2. Невыполнение медицинской организацией, участвующей в реализации программы государственных гарантий бесплатного оказания гражданам медицинской помощи, обязанности о предоставлении пациентам информации о порядке, об объеме и условиях оказания медицинской помощи в соответствии с программой государственных гарантий бесплатного оказания гражданам медицинской помощи -\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятнадцати тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 25.11.2013 № 317-ФЗ)","article_title":"Статья 6.30. Невыполнение обязанностей об информировании граждан о получении медицинской помощи в рамках программы государственных гарантий бесплатного оказания гражданам медицинской помощи и территориальных программ государственных гарантий бесплатного оказания гражданам медицинской помощи","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5e7f50076c2736b5c97d1434f01be8bb84af09400ecd9ab79195371a7e1b766"},{"code_id":"KoAP_RF","article_number":"6.31","version_date":"2001-12-30","article_text":"влечет предупреждение или наложение административного штрафа на должностных лиц в размере от двух тысяч до трех тысяч рублей; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет предупреждение или наложение административного штрафа на должностных лиц в размере от двух тысяч до трех тысяч рублей; на юридических лиц - от тридцати тысяч до сорока тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 119-ФЗ)","article_title":"Статья 6.31. Нарушение законодательства о донорстве крови и ее компонентов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f16d03954ea78ee7c005ec3b37188c6bfc58c83d59c7223520d2bc1aaf34bf05"},{"code_id":"KoAP_RF","article_number":"6.32","version_date":"2001-12-30","article_text":"1. Нарушение требований законодательства в сфере охраны здоровья о получении информированного добровольного согласия -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до трех тысяч рублей; на должностных лиц - от пяти тысяч до десяти тысяч рублей; на юридических лиц - от сорока тысяч до ста тысяч рублей.\n\n2. Нарушение сроков (в том числе при наличии медицинских и социальных показаний, а также учитывая сроки с момента обращения женщины в медицинскую организацию для искусственного прерывания беременности), установленных законодательством в сфере охраны здоровья для проведения искусственного прерывания беременности, -\n\nвлечет наложение административного штрафа на граждан в размере от четырех тысяч до пяти тысяч рублей; на должностных лиц - от десяти тысяч до тридцати тысяч рублей; на юридических лиц - от ста тысяч до ста пятидесяти тысяч рублей.\n\nПримечание. В целях настоящей статьи под гражданами понимаются медицинские работники, не являющиеся должностными лицами.\n\n(Дополнение статьей - Федеральный закон от 21.07.2014 № 243-ФЗ)","article_title":"Статья 6.32. Нарушение требований законодательства в сфере охраны здоровья при проведении искусственного прерывания беременности","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb7095fe2da0b78e93a7402da9f981a334a8770af592106c320ccf8d4f629f94"},{"code_id":"KoAP_RF","article_number":"6.33","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от семидесяти тысяч до ста тысяч рублей; на должностных лиц - от ста тысяч до шестисот тысяч рублей; на индивидуальных предпринимателей - от ста тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от одного миллиона до пяти миллионов рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на граждан в размере от семидесяти тысяч до ста тысяч рублей; на должностных лиц - от ста тысяч до шестисот тысяч рублей; на индивидуальных предпринимателей - от ста тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от одного миллиона до пяти миллионов рублей или административное приостановление деятельности на срок до девяноста суток.\n\nвлечет наложение административного штрафа на граждан в размере от семидесяти пяти тысяч до двухсот тысяч рублей; на должностных лиц - от ста пятидесяти тысяч до шестисот тысяч рублей; на индивидуальных предпринимателей - от ста пятидесяти тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двух миллионов до шести миллионов рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение частью - Федеральный закон от 01.04.2020 № 89-ФЗ)\n\nПримечание. Не являются административным правонарушением действия, предусмотренные частью 2 или 3 настоящей статьи, если реализация и (или) ввоз незарегистрированных лекарственных средств или медицинских изделий допускаются в соответствии с законодательством об обращении лекарственных средств и законодательством в сфере охраны здоровья, и (или) указанные лекарственные средства или медицинские изделия в Российской Федерации не производятся, и (или) указанные лекарственные средства или медицинские изделия рекомендованы к применению Всемирной организацией здравоохранения. (Дополнение примечанием - Федеральный закон от 01.04.2020 № 89-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 31.12.2014 № 532-ФЗ)","article_title":"Статья 6.33. Обращение фальсифицированных, контрафактных, недоброкачественных и незарегистрированных лекарственных средств, медицинских изделий и оборот фальсифицированных биологически активных добавок","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44a18a210992b57bb79b7357507c5f9ab358735171c9f0af4085f9637bf4db07"},{"code_id":"KoAP_RF","article_number":"6.34","version_date":"2001-12-30","article_text":"1. Производство или продажа лекарственных препаратов для медицинского применения без нанесения на них средств идентификации, предусмотренных законодательством Российской Федерации, либо с нарушением порядка их нанесения, установленного законодательством Российской Федерации, в случае обязательности нанесения таких средств идентификации, если эти действия (бездействие) не содержат признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей с конфискацией предметов административного правонарушения; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей с конфискацией предметов административного правонарушения.\n\n2. Несвоевременное внесение данных в систему мониторинга движения лекарственных препаратов для медицинского применения или внесение в нее недостоверных данных -\n\nвлечет наложение административного штрафа на должностных лиц в размере от пяти тысяч до десяти тысяч рублей; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 15.04.2019 № 58-ФЗ) (В редакции Федерального закона от 11.06.2021 № 204-ФЗ)","article_title":"Статья 6.34. Производство или продажа лекарственных препаратов для медицинского применения без нанесения средств идентификации либо с нарушением установленного порядка их нанесения либо несвоевременное внесение данных в систему мониторинга движения лекарственных препаратов для медицинского применения или внесение в нее недостоверных данных","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d7f64803c2ebe20f68a6c55ed4592374f1110b79a1b8ac93b32aa76511d8cc7"},{"code_id":"KoAP_RF","article_number":"6.35","version_date":"2001-12-30","article_text":"1. Несоблюдение санитарно-эпидемиологических требований к сбору, накоплению, транспортированию, обработке, утилизации или обезвреживанию отходов производства и потребления, за исключением случаев, предусмотренных частью 7 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до трех тысяч рублей; на должностных лиц - от тридцати тысяч до сорока тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пятидесяти тысяч до шестидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двухсот пятидесяти тысяч до трехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n2. Повторное в течение года совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до четырех тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от четырехсот тысяч до пятисот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n3. Действия (бездействие), предусмотренные частью 1 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от четырех тысяч до пяти тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от пятисот тысяч до шестисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n4. Несоблюдение санитарно-эпидемиологических требований к размещению отходов производства и потребления, за исключением случаев, предусмотренных частью 10 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от трех тысяч до пяти тысяч рублей; на должностных лиц - от сорока тысяч до пятидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от шестидесяти тысяч до семидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от трехсот пятидесяти тысяч до четырехсот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n5. Повторное в течение года совершение административного правонарушения, предусмотренного частью 4 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от шести тысяч до семи тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от восьмидесяти тысяч до девяноста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от шестисот тысяч до семисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n6. Действия (бездействие), предусмотренные частью 4 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от семи тысяч до восьми тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от девяноста тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от семисот тысяч до восьмисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n7. Несоблюдение санитарно-эпидемиологических требований к сбору, накоплению, транспортированию, обработке, утилизации или обезвреживанию отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от пяти тысяч до семи тысяч рублей; на должностных лиц - от пятидесяти тысяч до шестидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от семидесяти тысяч до восьмидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от четырехсот пятидесяти тысяч до пятисот пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n8. Повторное в течение года совершение административного правонарушения, предусмотренного частью 7 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от семи тысяч до восьми тысяч рублей; на должностных лиц - от шестидесяти тысяч до семидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от девяноста тысяч до ста тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от семисот тысяч до восьмисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n9. Действия (бездействие), предусмотренные частью 7 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от восьми тысяч до девяти тысяч рублей; на должностных лиц - от семидесяти тысяч до восьмидесяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста тысяч до ста десяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от восьмисот тысяч до девятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n10. Несоблюдение санитарно-эпидемиологических требований к размещению отходов животноводства -\n\nвлечет наложение административного штрафа на граждан в размере от восьми тысяч до десяти тысяч рублей; на должностных лиц - от семидесяти тысяч до девяноста тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от девяноста тысяч до ста десяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от шестисот тысяч до восьмисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n11. Повторное в течение года совершение административного правонарушения, предусмотренного частью 10 настоящей статьи, -\n\nвлечет наложение административного штрафа на граждан в размере от десяти тысяч до двенадцати тысяч рублей; на должностных лиц - от девяноста тысяч до ста тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста десяти тысяч до ста двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от восьмисот тысяч до девятисот тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n12. Действия (бездействие), предусмотренные частью 10 настоящей статьи, повлекшие причинение вреда здоровью людей или окружающей среде либо возникновение эпидемии или эпизоотии, если эти действия (бездействие) не содержат уголовно наказуемого деяния, -\n\nвлекут наложение административного штрафа на граждан в размере от двенадцати тысяч до четырнадцати тысяч рублей; на должностных лиц - от ста тысяч до ста десяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от ста двадцати тысяч до ста тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от девятисот тысяч до одного миллиона рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Дополнение статьей - Федеральный закон от 17.06.2019 № 141-ФЗ)","article_title":"Статья 6.35. Несоблюдение санитарно-эпидемиологических требований при обращении с отходами производства и потребления","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55d8c401c022d518345d5ff22bed8276ea1f1cf093acfef3d34edff3b6ac9654"},{"code_id":"KoAP_RF","article_number":"6.36","version_date":"2001-12-30","article_text":"Воспрепятствование в какой бы то ни было форме законной деятельности медицинского работника по оказанию медицинской помощи, за исключением случаев, предусмотренных частью 2 статьи 12.17 настоящего Кодекса, если это действие не содержит признаков уголовно наказуемого деяния, -\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 229-ФЗ)\n\nГЛАВА 7. АДМИНИСТРАТИВНЫЕ ПРАВОНАРУШЕНИЯ В ОБЛАСТИ ОХРАНЫ СОБСТВЕННОСТИ","article_title":"Статья 6.36. Воспрепятствование оказанию медицинской помощи","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dbfba4e21dbfad8df683ef93f1ec352cc3a3d548d5313c82e7601be193201bf8"},{"code_id":"KoAP_RF","article_number":"6.4","version_date":"2001-12-30","article_text":"Нарушение санитарно-эпидемиологических требований к эксплуатации жилых помещений и общественных помещений, зданий, сооружений и транспорта -\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от одной тысячи до двух тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от десяти тысяч до двадцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции федеральных законов от 09.05.2005 № 45-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 6.4. Нарушение санитарно-эпидемиологических требований к эксплуатации жилых помещений и общественных помещений, зданий, сооружений и транспорта","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85f8e57f0a61fcb10cd215e11cc277b14ac35e44ae6324f17cf58d99c29b8504"},{"code_id":"KoAP_RF","article_number":"6.5","version_date":"2001-12-30","article_text":"Нарушение санитарно-эпидемиологических требований к питьевой воде, а также к питьевому и хозяйственно-бытовому водоснабжению - (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от двух тысяч до трех тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двух тысяч до трех тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток.  (В редакции федеральных законов от 09.05.2005 № 45-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 6.5. Нарушение санитарно-эпидемиологических требований к питьевой воде","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"027c13aa8fc56e496f679155b3db60d19e66459d783a10b882ac13fa47bd33db"},{"code_id":"KoAP_RF","article_number":"6.6","version_date":"2001-12-30","article_text":"Нарушение санитарно-эпидемиологических требований к организации питания населения в специально оборудованных местах (столовых, ресторанах, кафе, барах и других местах), в том числе при приготовлении пищи и напитков, их хранении и реализации населению, -\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи до одной тысячи пятисот рублей; на должностных лиц - от пяти тысяч до десяти тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от пяти тысяч до десяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от тридцати тысяч до пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток. (В редакции Федерального закона от 22.12.2014 № 436-ФЗ)","article_title":"Статья 6.6. Нарушение санитарно-эпидемиологических требований к организации питания населения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13c81cee68d72e297823368726dedffcbdf9322caf4e4654c0758a9beb0edcbd"},{"code_id":"KoAP_RF","article_number":"6.7","version_date":"2001-12-30","article_text":"1. Нарушение санитарно-эпидемиологических требований к условиям отдыха и оздоровления детей, их воспитания и обучения, к техническим, в том числе аудиовизуальным, и иным средствам воспитания и обучения, к учебной мебели, а также к учебникам и иной издательской продукции -\n\nвлечет наложение административного штрафа на должностных лиц в размере от трех тысяч до семи тысяч рублей; на юридических лиц - от тридцати тысяч до семидесяти тысяч рублей.\n\nвлечет наложение административного штрафа на должностных лиц в размере от десяти тысяч до пятнадцати тысяч рублей; на юридических лиц - от ста тысяч до ста пятидесяти тысяч рублей или административное приостановление деятельности на срок до девяноста суток.\n\n(Статья в редакции Федерального закона от 05.06.2012 № 52-ФЗ)","article_title":"Статья 6.7. Нарушение санитарно-эпидемиологических требований к условиям отдыха и оздоровления детей, их воспитания и обучения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f16d0f05b838cf3515053ee70bc5bb0735ca04bffc25de6ca79b59731f75b38"},{"code_id":"KoAP_RF","article_number":"6.8","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 08.12.2003 № 161-ФЗ; от 19.05.2010 № 87-ФЗ)\n\nвлекут наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до пятнадцати суток.  (В редакции федеральных законов от 08.12.2003 № 161-ФЗ; от 22.06.2007 № 116-ФЗ; от 19.05.2010 № 87-ФЗ; от 28.12.2010 № 417-ФЗ)\n\nвлекут наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n(Дополнение частью - Федеральный закон от 28.12.2010 № 417-ФЗ)\n\nПримечание. Лицо, добровольно сдавшее приобретенные без цели сбыта наркотические средства, психотропные вещества, их аналоги или растения, содержащие наркотические средства или психотропные вещества, либо их части, содержащие наркотические средства или психотропные вещества, освобождается от административной ответственности за данное административное правонарушение. (В редакции Федерального закона от 19.05.2010 № 87-ФЗ)","article_title":"Статья 6.8. Незаконный оборот наркотических средств, психотропных веществ или их аналогов и незаконные приобретение, хранение, перевозка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a4b505d1ac75aca515500601c746d2174f29db8dad620a7bb1b625830137424"},{"code_id":"KoAP_RF","article_number":"6.9","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 03.02.2015 № 7-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до пятнадцати суток. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 28.12.2010 № 417-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей с административным выдворением за пределы Российской Федерации либо административный арест на срок до пятнадцати суток с административным выдворением за пределы Российской Федерации.\n\n(Дополнение частью - Федеральный закон от 28.12.2010 № 417-ФЗ)\n\nПримечание. Лицо, добровольно обратившееся в медицинскую организацию для лечения в связи с потреблением наркотических средств или психотропных веществ без назначения врача, освобождается от административной ответственности за данное правонарушение. Лицо, в установленном порядке признанное больным наркоманией, может быть с его согласия направлено на медицинскую и (или) социальную реабилитацию и в связи с этим освобождается от административной ответственности за совершение правонарушений, связанных с потреблением наркотических средств или психотропных веществ. Действие настоящего примечания распространяется на административные правонарушения, предусмотренные частью 2 статьи 20.20 настоящего Кодекса. (В редакции федеральных законов от 25.11.2013 № 313-ФЗ; от 25.11.2013 № 317-ФЗ; от 14.10.2014 № 307-ФЗ)","article_title":"Статья 6.9. Потребление наркотических средств или психотропных веществ без назначения врача либо новых потенциально опасных психоактивных веществ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"798c211ac09b96dcdbe25718fe6c0adfcee9801d3c4f795aebd08b750dcf52cc"},{"code_id":"KoAP_RF","article_number":"6.91","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 03.02.2015 № 7-ФЗ)\n\nУклонение от прохождения лечения от наркомании или медицинской и (или) социальной реабилитации лицом, освобожденным от административной ответственности в соответствии с примечанием к статье 6.9 настоящего Кодекса, либо уклонение от прохождения диагностики, профилактических мероприятий, лечения от наркомании и (или) медицинской и (или) социальной реабилитации лицом, на которое судьей возложена обязанность пройти диагностику, профилактические мероприятия, лечение от наркомании и (или) медицинскую и (или) социальную реабилитацию в связи с потреблением наркотических средств или психотропных веществ без назначения врача либо новых потенциально опасных психоактивных веществ, - (В редакции федеральных законов от 03.02.2015 № 7-ФЗ; от 28.11.2015 № 345-ФЗ)\n\nвлечет наложение административного штрафа в размере от четырех тысяч до пяти тысяч рублей или административный арест на срок до тридцати суток.\n\nПримечание. Лицо считается уклоняющимся от прохождения диагностики, профилактических мероприятий, лечения от наркомании и (или) медицинской и (или) социальной реабилитации в связи с потреблением наркотических средств или психотропных веществ без назначения врача либо новых потенциально опасных психоактивных веществ, если оно не посещает или самовольно покинуло медицинскую организацию или учреждение социальной реабилитации либо не выполнило более двух раз предписания лечащего врача. (В редакции Федерального закона от 03.02.2015 № 7-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 25.11.2013 № 313-ФЗ)","article_title":"Статья 6.91. Уклонение от прохождения диагностики, профилактических мероприятий, лечения от наркомании и (или) медицинской и (или) социальной реабилитации в связи с потреблением наркотических средств или психотропных веществ без назначения врача либо новых потенциально опасных психоактивных веществ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06fd086f1e398ebf06ac6c776590e36358d5b08a00b8fb9f58e07357c4120fac"},{"code_id":"KoAP_RF","article_number":"7.1","version_date":"2001-12-30","article_text":"Самовольное занятие земельного участка или части земельного участка, в том числе использование земельного участка лицом, не имеющим предусмотренных законодательством Российской Федерации прав на указанный земельный участок, -\n\nвлечет наложение административного штрафа в случае, если определена кадастровая стоимость земельного участка, на граждан в размере от 1 до 1,5 процента кадастровой стоимости земельного участка, но не менее пяти тысяч рублей; на должностных лиц - от 1,5 до 2 процентов кадастровой стоимости земельного участка, но не менее двадцати тысяч рублей; на юридических лиц - от 2 до 3 процентов кадастровой стоимости земельного участка, но не менее ста тысяч рублей, а в случае, если не определена кадастровая стоимость земельного участка, на граждан в размере от пяти тысяч до десяти тысяч рублей; на должностных лиц - от двадцати тысяч до пятидесяти тысяч рублей; на юридических лиц - от ста тысяч до двухсот тысяч рублей.\n\nПримечания:\n\n1. За административные правонарушения, предусмотренные настоящей статьей, лица, осуществляющие предпринимательскую деятельность без образования юридического лица, несут административную ответственность как юридические лица.\n\n2. В случае самовольного занятия части земельного участка административный штраф, рассчитываемый из размера кадастро\n\nвой стоимости земельного участка, исчисляется пропорционально площади самовольно занятой части земельного участка.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 46-ФЗ)","article_title":"Статья 7.1. Самовольное занятие земельного участка","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8edf2f8a20499d58d47f589a8d25e217c515a2101aaa39366ea21aa9c5cf3a58"},{"code_id":"KoAP_RF","article_number":"7.10","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 04.12.2006 № 201-ФЗ; от 28.12.2009 № 380-ФЗ)\n\nСамовольная уступка права пользования землей, недрами, лесным участком или водным объектом, а равно самовольная мена земельного участка - (В редакции федеральных законов от 04.12.2006 № 201-ФЗ; от 28.12.2009 № 380-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.10. Самовольная уступка права пользования землей, недрами, лесным участком или водным объектом","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c0d82398e8c7ee19511a2e47b0f02af7de36fc1f99df034dba228e7eaf28c4a"},{"code_id":"KoAP_RF","article_number":"7.11","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 06.12.2007 № 333-ФЗ; от 24.07.2009 № 209-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятисот до одной тысячи рублей; на должностных лиц - от одной тысячи до двух тысяч рублей; на юридических лиц - от десяти тысяч до двадцати тысяч рублей. (В редакции Федерального закона от 22.06.2007 № 116-ФЗ)\n\nвлечет лишение права осуществлять охоту на срок от одного года до трех лет.\n\n(Дополнение частью - Федеральный закон от 23.07.2013 № 201-ФЗ)","article_title":"Статья 7.11. Пользование объектами животного мира и водными биологическими ресурсами без разрешения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1fd4215b1130886dfccc40b505eaa2af041fc1c44f149f610b73a73c0f007e7c"},{"code_id":"KoAP_RF","article_number":"7.12","version_date":"2001-12-30","article_text":"влечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей с конфискацией контрафактных экземпляров произведений и фонограмм, а также материалов и оборудования, используемых для их воспроизведения, и иных орудий совершения административного правонарушения; на должностных лиц - от десяти тысяч до двадцати тысяч рублей с конфискацией контрафактных экземпляров произведений и фонограмм, а также материалов и оборудования, используемых для их воспроизведения, и иных орудий совершения административного правонарушения; на юридических лиц - от тридцати тысяч до сорока тысяч рублей с конфискацией контрафактных экземпляров произведений и фонограмм, а также материалов и оборудования, используемых для их воспроизведения, и иных орудий совершения административного правонарушения.  (В редакции федеральных законов от 27.12.2005 № 193-ФЗ; от 22.06.2007 № 116-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч рублей; на должностных лиц - от десяти тысяч до двадцати тысяч рублей; на юридических лиц - от тридцати тысяч до сорока тысяч рублей. (В редакции федеральных законов от 27.12.2005 № 193-ФЗ; от 22.06.2007 № 116-ФЗ)","article_title":"Статья 7.12. Нарушение авторских и смежных прав, изобретательских и патентных прав","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7756505191d235419bc8eea63dd4eea5b0931657b36ef7c86c063df3a8d3baef"},{"code_id":"KoAP_RF","article_number":"7.13","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 30.12.2015 № 459-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до двухсот тысяч рублей; на должностных лиц - от двадцати тысяч до четырехсот тысяч рублей; на юридических лиц - от двухсот тысяч до пяти миллионов рублей.\n\nвлекут наложение административного штрафа на граждан в размере от двадцати тысяч до трехсот тысяч рублей; на должностных лиц - от пятидесяти тысяч до пятисот тысяч рублей; на юридических лиц - от одного миллиона до двадцати миллионов рублей.\n\nвлекут наложение административного штрафа на граждан в размере от пятнадцати тысяч до ста тысяч рублей; на должностных лиц - от двадцати тысяч до трехсот тысяч рублей; на юридических лиц - от ста тысяч до одного миллиона рублей.\n\nвлечет наложение административного штрафа в размере от ста тысяч до шестисот тысяч рублей.\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до ста тысяч рублей; на должностных лиц - от двадцати тысяч до трехсот тысяч рублей; на юридических лиц - от ста тысяч до одного миллиона рублей.\n\n(Дополнение частью - Федеральный закон от 30.12.2015 № 459-ФЗ)\n\n(Статья в редакции Федерального закона от 07.05.2013 № 96-ФЗ)","article_title":"Статья 7.13. Нарушение требований законодательства об охране объектов культурного наследия (памятников истории и культуры) народов Российской Федерации","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"553f5f4fb20ed425620add3ddf6b96550d6a13254589ebf0a0f33904acda4f72"},{"code_id":"KoAP_RF","article_number":"7.14","version_date":"2001-12-30","article_text":"(Наименование в редакции федеральных законов от 07.05.2013 № 96-ФЗ; от 23.06.2016 № 222-ФЗ)\n\nОрганизация или проведение земляных, строительных, мелиоративных, хозяйственных и иных работ без разрешения государственного органа охраны объектов культурного наследия в случаях, если такое разрешение обязательно, -   (В редакции Федерального закона от 07.05.2013 № 96-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до ста тысяч рублей; на должностных лиц - от двадцати тысяч до трехсот тысяч рублей; на юридических лиц - от ста тысяч до одного миллиона рублей.  (В редакции Федерального закона от 07.05.2013 № 96-ФЗ)","article_title":"Статья 7.14. Организация или проведение земляных, строительных или иных работ без разрешения органа, осуществляющего государственный надзор за состоянием, содержанием, сохранением, использованием, популяризацией и государственной охраной объектов культурного наследия","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"232b47bc3acf41b2572a716384c554a2633ac6f54b873b4a67e096d6a892df4c"},{"code_id":"KoAP_RF","article_number":"7.141","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 22.10.2014 № 315-ФЗ)\n\n1. Уничтожение или повреждение объектов культурного наследия (памятников истории и культуры) народов Российской Федерации, в том числе выявленных объектов культурного наследия, -\n\nвлечет наложение административного штрафа на юридических лиц в размере от пятисот тысяч до двадцати миллионов рублей.\n\n2. Действия (бездействие), предусмотренные частью 1 настоящей статьи, совершенные в отношении особо ценных объектов культурного наследия народов Российской Федерации либо объектов культурного наследия, включенных в Список всемирного наследия, -\n\nвлекут наложение административного штрафа на юридических лиц в размере от одного миллиона до шестидесяти миллионов рублей.\n\n3. Уничтожение или повреждение объектов, составляющих предмет охраны исторического поселения, -\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до двухсот тысяч рублей; на должностных лиц - от двадцати тысяч до четырехсот тысяч рублей; на юридических лиц - от двухсот тысяч до пяти миллионов рублей.\n\n(Дополнение частью - Федеральный закон от 22.10.2014 № 315-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 96-ФЗ)","article_title":"Статья 7.141. Уничтожение или повреждение объектов культурного наследия (памятников истории и культуры) народов Российской Федерации, объектов, составляющих предмет охраны исторического поселения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2968fee903bc68b81229e243839a96e5efea7fa613786b3870d3fa4220ea67b7"},{"code_id":"KoAP_RF","article_number":"7.142","version_date":"2001-12-30","article_text":"в случае обнаружения объекта, обладающего признаками объекта культурного наследия, или работ, проведение которых может ухудшить состояние объекта культурного наследия либо нарушить его целостность и сохранность\n\nНеисполнение заказчиком и (или) лицом, проводящим земляные, строительные, дорожные или иные работы, обязанности по приостановлению указанных работ в случае обнаружения объекта, обладающего признаками объекта культурного наследия в соответствии с законодательством об охране объектов культурного наследия, в том числе объекта археологического наследия, или работ, проведение которых может ухудшить состояние объекта культурного наследия либо нарушить его целостность и сохранность, после получения письменного предписания государственного органа охраны объектов культурного наследия -  (В редакции Федерального закона от 22.10.2014 № 315-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от пятнадцати тысяч до трехсот тысяч рублей; на должностных лиц - от двадцати тысяч до четырехсот тысяч рублей; на юридических лиц - от двухсот тысяч до пяти миллионов рублей.\n\n(Дополнение статьей - Федеральный закон от 07.05.2013 № 96-ФЗ)","article_title":"Статья 7.142. Неисполнение обязанности по приостановлению работ","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bdb129bdb7d26dd82a631222f949e9b1d0d76ed2a87cb5eca69813d4191ebcc"},{"code_id":"KoAP_RF","article_number":"7.15","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 30.12.2015 № 459-ФЗ)\n\nвлечет наложение административного штрафа на граждан в размере от одной тысячи пятисот до двух тысяч пятисот рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ; на должностных лиц - от четырех тысяч до пяти тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ; на юридических лиц - от сорока тысяч до пятидесяти тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ. (В редакции федеральных законов от 22.06.2007 № 116-ФЗ; от 30.12.2015 № 459-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от пятнадцати тысяч до трехсот тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ; на должностных лиц - от пятидесяти тысяч до шестисот тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ; на юридических лиц - от одного миллиона до десяти миллионов рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ.  (В редакции Федерального закона от 30.12.2015 № 459-ФЗ)\n\n(Часть в редакции Федерального закона от 07.05.2013 № 96-ФЗ)\n\nвлекут наложение административного штрафа на граждан в размере от двух тысяч до двух тысяч пятисот рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ, и специальных технических средств поиска и (или) землеройных машин; на должностных лиц - от четырех тысяч пятисот до пяти тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ, и специальных технических средств поиска и (или) землеройных машин; на юридических лиц - от пятидесяти тысяч до ста тысяч рублей с конфискацией предметов, добытых в результате археологических полевых работ, а также инструментов и оборудования, использованных для археологических полевых работ, и специальных технических средств поиска и (или) землеройных машин. (В редакции Федерального закона от 30.12.2015 № 459-ФЗ)\n\n(Дополнение частью - Федеральный закон от 23.07.2013 № 245-ФЗ)\n\nПримечание. Под специальными техническими средствами поиска в настоящей статье понимаются металлоискатели, радары, магнитные приборы и другие технические средства, позволяющие определить наличие археологических предметов в месте залегания. (Дополнение примечанием - Федеральный закон от 23.07.2013 № 245-ФЗ)\n\n(Статья в редакции Федерального закона от 26.07.2006 № 133-ФЗ)","article_title":"Статья 7.15. Проведение археологических полевых работ без разрешения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf88b34e50b513ba6404f7e49ee820a8a1ef95eb8adeb90791f4ca5643d51d8a"},{"code_id":"KoAP_RF","article_number":"7.151","version_date":"2001-12-30","article_text":"Совершение сделок с археологическими предметами в нарушение требований, установленных законодательством Российской Федерации, -\n\nвлечет наложение административного штрафа на граждан в размере от двух тысяч до пяти тысяч рублей с конфискацией археологических предметов; на должностных лиц - от двадцати тысяч до пятидесяти тысяч рублей с конфискацией археологических предметов; на юридических лиц - от трехсот тысяч до восьмисот тысяч рублей с конфискацией археологических предметов.\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 245-ФЗ)","article_title":"Статья 7.151. Незаконный оборот археологических предметов","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45680e08cd0137c7cb4233e28e9f008576edd8787ca7a6b78852521c55d9511b"},{"code_id":"KoAP_RF","article_number":"7.16","version_date":"2001-12-30","article_text":"(Наименование в редакции Федерального закона от 02.12.2013 № 342-ФЗ)\n\nНезаконное изменение правового режима земельных участков, отнесенных к землям историко-культурного назначения, -   (В редакции Федерального закона от 02.12.2013 № 342-ФЗ)\n\nвлечет наложение административного штрафа на должностных лиц в размере от двадцати тысяч до четырехсот тысяч рублей. (В редакции Федерального закона от 07.05.2013 № 96-ФЗ)\n\n(Статья в редакции Федерального закона от 28.12.2009 № 380-ФЗ)","article_title":"Статья 7.16. Незаконное изменение правового режима земельных участков, отнесенных к землям историко-культурного назначения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9248ae2d86f626087b4bf6d87809bec3458d1464d6faea36fd3957b7ccde4eef"}]$law7v019$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
